window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_022"]={"n":"王恽","dyn":"元","poems":[{"t":"过沙沟店","f":"七言律诗","c":["高柳长涂送客吟，暗惊时序变鸣禽。","清风破暑连三日，好雨依时抵万金。","远岭抱枝围野色，行云随马弄轻阴。","摇鞭喜入肥城界，桑柘阴浓麦浪深。"]},{"t":"卜算子","f":"曲","c":["一抹截头云，叆叇从龙发。","尾足连卷见半空，霁色翻苍鬣。","举手欲攀鳞，散我麒麟发。","天外雄风秘化机，吹落苍烟峡。"]},{"t":"三奠子","f":"曲","c":["壮河山表里，百二喉襟。","形胜地，古犹今。","风云全晋在，草木故都深。","淡长空，孤鸟没，总消沉。","东山高卧，梁甫长吟。","人未老，鬓毛侵。","平生多古意，落日更登临。","倚危阑，穷远目，恐伤心。"]},{"t":"三奠子","f":"曲","c":["湛新秋风露，暧暧微霄。","梧叶下，桂香飘。","鹊翻银汉水，人渡玉兰桥。","欢能几，虹影断，渚宫遥。","人闲多巧，天上无憀。","今古恨，苦相撩。","果瓜丝曲缀，儿女思空饶。","层轩晚，香露湿，可怜宵。"]},{"t":"三奠子","f":"曲","c":["怅神光奕奕，天上良宵。","花露湿，翠钗翘。","风回鸾扇影，愁满紫云轺。","恨相望，虽一水，隔三桥。","朱弦寂寂，心思迢迢。","人未老，鬓先雕。","翻腾惊世故，机巧到鲛绡。","凉夜永，箫声咽，篆烟飘。"]},{"t":"三奠子","f":"曲","c":["隔盈盈一水，欢会今宵。","梧叶上，雨萧萧。","星沉开帐烛，云黯渡河桥。","渚宫深，离思苦，两无憀。","金针缕细，彩舫花娇。","儿女辈，漫情饶。","巧来心愈拙，弦促韵难调。","西楼月，银汉影，碧天遥。"]},{"t":"三奠子 都城七夕","f":"曲","c":["渺新秋节物，客思天涯。","岩桂重，碧云赊。","烟华萦紫禁，心事梦长沙。","青铜里，人未老，鬓先华。","钩帘望月，得巧谁家。","儿女辈，语空哗。","露翻梧叶重，河映绮楼斜。","倾云液，歌金缕，岸乌纱。"]},{"t":"凤凰台上忆吹箫","f":"曲","c":["宫树春空，御屏香冷，谁遗金碗人间。","爱一枝紫玉，双凤声蟠。","秋月春花客思，把幽情、都付伊传。","惊吹处，籁翻天吹。","鹤怨空山。","风流贵家公子，记梦里琼楼，稳跨苍鸾。","恍露凝银浦，霜裂琅玕。","不见云间弄玉，余音散、赤壁江寒。","秦台晚，碧云零乱瑶天。"]},{"t":"凤凰台上忆吹箫 赠乔媪张氏","f":"曲","c":["碧凤翘寒，玉宵宫晚，云窗误读黄庭。","恨凌波罗袜，洛浦尘生。","往事风流云散，但翠衾、冷落余馨。","人何在，淡妆缟袂，幽树柴荆。","相逢一尊芳酒，对夜色疏星，歌袅云停。","记水南佳丽，姚魏池亭。","梦绕芙蓉城阙，归驭稳、缑岭风清。","桃花晚，等闲休负瑶英。"]},{"t":"太常引","f":"曲","c":["春风碧水静林丘。","对书史，日优游。","来往更风流。","问谁似、东陵故侯。","黄陂襟度，曲江誉望，山立看扬休。","春酿尽禁篘。","拚醉尽、蟠桃上秋。"]},{"t":"太常引","f":"曲","c":["北平移镇入咸秦。","说睿眷，更情亲。","下手见经纶。","道好个、中原老臣。","万屯晓日，一鞭农事，泾水画中春。","陆海尽藏珍。","似只欠、封侯富民。"]},{"t":"太常引 为万奴总管寿","f":"曲","c":["重于山岳蔼如兰。","喜一旦，得同官。","裁鉴笑谈间。","道不似、当年将坛。","一年好处，中秋节近，凉露洗金盘。","丹桂月中看。","尽耐得、人间岁寒。"]},{"t":"太常引 为王同知寿","f":"曲","c":["雍容诗礼冠时髦。","都忘却，贵人骄。","横槊见英标。","道勇似、当年嫖姚。","默含万动，德尊一府，歌寿听民谣。","绿鬓映金貂。","尽千尺、青松后雕。"]},{"t":"太常引 寿刘同知","f":"曲","c":["太行晴色泛帘钩。","对书史，日优游。","宾从尽风流。","谁健似、东陵故侯。","人间万事，尘埃野马，一笑付纹楸。","眉宇寿光浮。","拚醉过、黄花暮秋。"]},{"t":"太常引 寿庞咨议","f":"曲","c":["髯郎风度幕中莲。","已师范，使君贤。","骥足快腾骞。","道好个、庞家士元。","沧浪高兴，寒花晚节，秋色满淇园。","一盏愿遐年。","要都酿、君家百泉。"]},{"t":"太常引 寿陶珉溪","f":"曲","c":["南枝梅信点冰妍。","觉初度，得春偏。","人物鳣堂仙。","看才思、浑如涌泉。","悠悠往古，纷纷俗学，鞶帨绣空鲜。","青鬓莫苍然。","要折衷、陶家讲筵。"]},{"t":"太常引 周都运生朝时添寿王村","f":"曲","c":["量蟠英伟气和愉。","道沧海，得遗珠。","忠义与心俱。","见漕府、归来转输。","山呈霁色，杯添野水，春满野人庐。","郑重万金躯。","要羽翼、当年汉储。"]},{"t":"太常引 送王嘉父","f":"曲","c":["去年鞍马客南鄘。","柰告别，苦匆匆。","今岁又相逢。","喜客舍、清尊屡同。","仲宣楼上，杜陵幕下，着处话途穷。","好去汉元龙。","道休着、青春负公。"]},{"t":"太常引 送段信卿拜河东宪司经历","f":"曲","c":["北来孤剑郁苍颜。","听时事，立谈闲。","秋隼正腾翻。","莫便倚、霜空陡寒。","太行秋色，汾川雁影，极目送归鞍。","簿领宪司闲。","道好个、河东幕官。"]},{"t":"忆秦娥","f":"曲","c":["花时乐。","醁尊记醉平津阁。","平津阁。","一声金缕，满阶红叶。","小阑此日情萧索。","土膏一寸春如削。","春如削。","几时盼到，绛灯红烁。"]},{"t":"忆秦娥","f":"曲","c":["华阳阁。","一年心赏中秋约。","中秋约。","九霄风露，有怀都豁。","挂香和雨风吹落。","倚阑望处秋烟薄。","秋烟薄。","一尊能与，素娥同酌。"]},{"t":"木兰花慢","f":"曲","c":["壮东南一柱，分阃寄，事非轻。","见雨露思纶，河山带砺，勋府元盟。","依依汴堤杨柳，甚一朝、光彩动旗旌。","晓日千梁浮蝀，春风百雉严城。","临轩鼙鼓正凝情。","忠孝旧家声。","看奕世功名，麒麟高阁，宛转丹青。","绿波北潭花影，又一年、春好是清明。","彩袖一杯寿了，望中三楚云平。"]},{"t":"木兰花慢","f":"曲","c":["远风台上客，说雅集，玉生光。","纵尊俎无情，登临佳节，此兴能忘。","龙山会君莫羡，爱绿萝、影里到山庄。","骢马长安清贵，留连春草池塘。","渊明肮脏傍门旁。","多病对秋香。","怅岁晚田荒，几多稂莠，薿薿登场。","人间事，如意少，且同来、一笑共匡床。","寄谢牛山公子，何须挥涕残阳。"]},{"t":"木兰花慢","f":"曲","c":["叹西山归客，又愁里，过清明。","记幕燕巢倾，朝堂人去，往事堪惊。","行藏固非人力，顿尘缨、终愧草堂灵。","潘岳无间可赋，渊明何地堪耕。","汉家一论到书生。","六合望澄清。","甚楼上元龙，山中宰相，何止虚名。","当年卧龙心事，尽羽毛、千古见青冥。","憔悴中堂故吏，醉来老泪纵横。"]},{"t":"木兰花慢","f":"曲","c":["爱春光淡沱，歌吹暖，竹西亭。","正花簇金鞍，香翻雪树，碧酒同倾。","谁将翠帷双卷，拥红妆、临水照娉婷。","缥缈凌波仙子，依稀罗袜尘生。","使君高兴动青冥。","心事怯流莺。","对如画江山，一时豪杰，湖海交情。","自怜鬓华如此，且相逢、一笑惜飘零。","明日河阳客舍，春风柳色青青。"]},{"t":"木兰花慢","f":"曲","c":["怅居庸北口，爱苍霭，拥千岑。","淡秋满陪京，翠华南狩，万骑骎骎。","从千宫□□□，望清尘、拜听车音。","日月中天统在，风云龙虎台深。","马迁留滞卧周南。","恋阙破丹心。","恨伏枕悠悠，情关药裹，梦共秋衾。","岂知金镳野鹿，恐暮年、分薄是长林。","却为有恩未报，许身愧比南金。"]},{"t":"木兰花慢","f":"曲","c":["爱双鸣栖凤，趁舞袖，共婆娑。","恨叠鼓凝笳，繁弦急管，悲壮何多。","金泥小檀花面，尽凄清、翻尽雪儿歌。","幄殿悄闻私语，铜龙冷籁秋波。","明妆高烛洗金荷。","心赏重经过。","听一曲流连，珠帘画栋，几度斜河。","红云岛，仙音部，说新声、得意掩云和。","看取长安日近，春风摇荡鸣珂。"]},{"t":"木兰花慢","f":"曲","c":["老西山倦客，喜今岁，是归年。","笑镜里衰容，吟边华发，薄宦流连。","功名事无有分，且旧鞭、休羡祖生先。","望里芙蓉大府，梦余禅榻茶烟。","恨无明略卧林泉。","平子太拘牵。","尽俯首辕驹，寸心能了，犹胜归田。","前途事，如抹漆，又向谁、重理伯牙弦。","自是一生心苦，非关六印腰悬。"]},{"t":"木兰花慢","f":"曲","c":["淡中庭暝色，初遣奠，夜寒凄。","对草草杯盘，昏昏灯火，客里京师。","比量旧年心事，笑蹉跎、书剑向来非。","谁着朱衣白兰，春风三拜龙墀。","山妻稚子竟何为。","温饱汝嘻嘻。","怅故国丘山，苍烟乔木，卿月空辉。","葵心要须倾日，道等闲、休遣镜鸾知。","自信苍颜如铁，不堪双鬓如丝。"]},{"t":"木兰花慢","f":"曲","c":["六合一家统，依日月，到重光。","道太岱封书，云龙接踵，此意难忘。","西园万花绣错，好枕中、蝶花似蒙庄。","敛翅深栖金粉，贪芳更度银塘。","一生白眼贵人旁。","赢得姓名香。","几戏影棚边，随人鼓笛，贺老当场。","虽可笑，犹有用，似也胜、陈许怒争床。","静想行藏有命。","且休眼热王阳。"]},{"t":"木兰花慢","f":"曲","c":["问东城春色，正谷雨，牡丹期。","想前日芳苞，近来绛艳，红烂灯枝。","刘郎为花情重，约柳边、娃馆醉吴姬。","罗袜凌波微步，玉盘承露低垂。","春风百匝绣罗围。","看到彩云飞。","甚着意追欢，留连光景，回首差池。","半春短长亭畔，漫一杯、藉草对斜晖。","归纵酴醾雪在，不堪姚魏离枝。"]},{"t":"木兰花慢","f":"曲","c":["宪陵台畔客，笑几度，送人行。","对一道青山，两行官柳，去住人情。","苍生望初不系。","问此身、何用绊虚名。","宦味真成画饼，隐居却伴侯鲭。","十年惭愧草堂灵。","自分苦飘零。","甚一片闲云，几回归梦，野钓林耕。","浮沉待从里社，觉倘来、轩冕总堪惊。","寄谢竹林旧友，且休笔削寒盟。"]},{"t":"木兰花慢","f":"曲","c":["问城南北柳，最好处，胜游乡。","对湖水微茫，瑶翻碧潋，修禊浮觞。","比量今春乐事，忆去年、书剑共游梁。","晓日繁台古寺，春风碧草宫墙。","人生离别是寻常。","两岁喜徜徉。","更金缕新声，佳人锦瑟，踏遍春阳。","多君岁寒心在，似西溪、松柏郁苍苍。","记得醉时笑语，梦回枕上犹香。"]},{"t":"木兰花慢","f":"曲","c":["烂云衢彩婺，和晓月，满庭闱。","正梅粉香飘，林梢紫动，淑景初迟。","观津盛传王氏，道孝心、重见老莱衣。","和气一家瑞霭，慈颜九十柔仪。","香烧静院趁朝晖。","未省杖扶持。","纵德厚流长，遐龄能健，此事应稀。","婆娑绿萱堂背，爱一竿、苍竹六孙枝。","照映西山秀色，年年翠点修眉。"]},{"t":"木兰花慢 为史总帅尊夫人之寿","f":"曲","c":["霭长筵拜庆，似眉寿，几人同。","更绿发垂肩，方瞳炯漆，五福尊崇。","风流大家仪范，甚能移、子孝作臣忠。","猎猎征东汉旆，堂堂南下殊功。","一江春醉醒中。","都卷入歌钟。","看和气怡声，承颜起舞，袖锦翻红。","云闲婺光分彩，尽萧然、林下谢家风。","笑拥满庭兰玉，年年乐事无穷。"]},{"t":"木兰花慢 为张詹事寿","f":"曲","c":["爱承华詹尹，尽明略，更雄襟。","甚潇洒清吟，半生梦寐，铜辇秋衾。","莫论量，归计早，恐未容、亭扁遂初心。","共道东山丝竹，风云两袖商霖。","春坊桃李清阴。","气干郁千寻。","看他日明堂，圆杈偃植，栋宇雄沉。","家近上林春早，觉桂香、浮酒动华簪。","满酌一杯为寿、鲁连不用千金。"]},{"t":"木兰花慢 寿史中丞","f":"曲","c":["相门佳公子，都忘却，贵人骄。","有万石忠动，伯鱼诗礼，才气飘飘。","风流谢家玉树，说妙龄、英誉冠东朝。","桂殿亲承弓砚，豸冠高映金貂。","两台清议耸风标。","睿眷见恩饶。","要宝瑟朱弦，羹梅伊鼎，试手更调。","凤凰池，还浴凤，看羽毛、奕世动云霄。","郑重岁寒贞节，青松千尺难雕。"]},{"t":"木兰花慢 寿崔子文","f":"曲","c":["际河山两界，道此地，正文冲。","才北渚离筵，南亭奔迓，终岁倥偬。","风流故家从事，暂淹留、莲幕簿书丛。","更办锦笺诗句，笔端晕碧裁红。","今朝寿席且从容。","宾客喜相同。","就雪蚁浮香，眉毫舒彩，莫放杯空。","人生正须适意，尽冰梢、蜡蒂未冲融。","海曲尚存遗爱，稼齐自有春风。"]},{"t":"木兰花慢 和国范郎中见赠严韵","f":"曲","c":["卧孤松云壑，爱青贯，四时心。","自绝涧幽蟠，苍烟高拥，气压千林。","冰霜几年凌傲，甚九天、一日露恩深。","白壁无双国士，朱弦三叹遗音。","春风草木变萧森。","又复见雄襟。","想直犯龙颜，片言曾霁，万里重阴。","相逢莫惊白首，更明时、几世似于今。","只恐南阳垄底，空怀梁父长吟。"]},{"t":"木兰花慢 居庸怀古","f":"曲","c":["壮巉巉铁峡，谁设险，劈苍岑。","拥万里风烟，一栓横锁，形胜雄沉。","汉王阳□□□，忆当年、叱驭走骎骎。","半夜邮亭索酒，平明燕市长吟。","追思往事不堪寻。","山色古犹今。","甚三十年来，青云垂翅，素发鬅鬙。","投闲却教应聘，笑委身、从事老难任。","立遍西风残照，山光翠满疏林。"]},{"t":"木兰花慢 寄王宣慰立夫","f":"曲","c":["浩鱼龙泺海，曾同醉，凤凰楼。","记猎较河南，并持英荡，千里长游。","风流故家人物，爱赋诗、鞍马气横秋。","落日隆中怀古，薰风洛水浮舟。","重逢春色入东州。","小试统清流。","看生啸江淮，风连台阁，名动金瓯。","经纶半生心事，细推量、合在百花头。","此日清香画戟，不应谈笑封侯。"]},{"t":"木兰花慢 望郝奉使墓","f":"曲","c":["洒西风老泪，又马上，望郎山。","对红露秋香，芙蓉城阙，依旧雄藩。","碧云故人何在，忆扶摇、九万看鹏抟。","赋就凤凰楼晚，星沉鹦鹉洲寒。","一丘宿草锁苍烟。","零落复何言。","似燕许才名，风云际会，自古天悭。","皇皇使华南下，爱丹衷、拟缔两朝欢。","恨煞奸回秋壑，月明愁满江干。"]},{"t":"木兰花慢 赋白莲和王西溪","f":"曲","c":["爱玉华仙供，偶移影，下瑶池。","怅野渚苍烟，结根非所，繁艳争欺。","风清月寒半坠，道无情、有恨欲谁知。","罗袜凌波微步，淡香高韵幽姿。","风烟首梦共溪。","采采画船归。","趁粉露和香，秋光细酿，琼液淋漓。","招呼谪仙共饮，记两舷、脚踏醉吴姬。","一曲清吟未了，翠盘狼藉珠玑。"]},{"t":"木兰花慢 赋红梨花","f":"曲","c":["爱一枝香雪，几暮雨，洗妆残。","尽空谷幽居，佳人寂寞，泪粉阑干。","芳姿似嫌雅淡，问谁将、大药驻朱颜。","塞上胭脂夜紫，雪边蝴蝶朝寒。","风流韵远更清闲。","醉眼入惊看。","甚底事坡仙，被花热恼，惆怅东兰。","细倾玉瓶春酒，待月中、横笛倩云鬟。","吹散碧桃千树，尽随流水人间。"]},{"t":"木兰花慢 赋芙蓉杏花","f":"曲","c":["听夜来微雨，甚一霎，过东墙。","爱活色生香，芙蓉标格，暖贮春光。","珑松宝团琼缀，笑海棠、能睡更无香。","烂漫宋郎心眼，风流时世新妆。","少年走马杏花冈。","句惹兴偏长。","记夸酒青旗，树头招飐，唤客初尝。","别来吴姬粉面，比旧年、风韵转芬芳。","似觉生红闹意，未容说与东皇。"]},{"t":"木兰花慢 赋酴醾","f":"曲","c":["爱雪团娇小，开较晚，尽春融。","似麝染沉薰，檀轻粉薄，费尽春工。","绿阴小庭晴昼，放绣帘、轻度竹梢风。","待着一天香韵，醉吟留伴诗翁。","洗妆不用露华浓。","玉树湿青葱。","欲细挽柔条，重围锦幄，不放春空。","春残未应多恨，道典型、犹在酒杯中。","何似留芳翠枕，夜深归梦瑶宫。"]},{"t":"水龙吟","f":"曲","c":["相逢一醉金荷，气豪长恨欢娱少。","貂蝉贵待，内家声伎，琵琶最好。","铁拨鹍丝，划然中有，繁音急调。","笑黄云出塞，青衫拭泪，恩怨事，君休道。","且听新声硬抹，更银筝、与相缭绕。","空堂雪辊，玉盘珠迸，清雄缥缈。","汉殿承恩，侯藩作牧，此心未老。","付曲中细写，他年事业，拜红云岛。"]},{"t":"水龙吟","f":"曲","c":["窈然碧玉池方，绿波不见还凝伫。","翠萍痕在，金支光淡，湘妃无语。","瑶瑟声沉，画兰愁绝，几回如许。","甚风烟依约，鱼龙黯惨，空回首，珠帘暮。","一夕翠华临幸，也悲凉、故宫尘土。","石根碧涨，天飘翻出，黑湾雷雨。","思舜亭高，风漪吹散，满空秋暑。","欲苍梧回叫，凤箫凄断，听躬耕处。"]},{"t":"水龙吟","f":"曲","c":["春风绿绮堂深，尊前初识龟年面。","烟花紫禁，几年供奉，香飘合殿。","悲壮凄清，九天飞下，凤吟莺啭。","待近前细看，品题银字，知还是，红牙管。","尽着金簧玉磬，泛宫声、五音初遍。","朋簪四合，回头听处，少陵情惋。","绿酒抛春，何心倾倒，汾阳金碗。","为斯人少漏，玉堂消息，写清商怨。"]},{"t":"水龙吟","f":"曲","c":["绿杨一道飞花，绣衣乱点如晴雪。","玉瓶酒尽，阳关歌彻，未容轻发。","绿绮论心，几人得似，刘君风节。","记山堂轰醉，已成陈迹，今又作，东城别。","世事悠悠谁料，淡长空、孤鸿明灭。","老怀耿耿，正须自信，坚弥百折。","白发灰心，平生留在，情驰丹阙。","怅孤云细草，东州回望，恨高城隔。"]},{"t":"水龙吟","f":"曲","c":["日边俪景同翻，千年高际风云会。","堂堂大节，中流砥柱，狂澜横制。","黄阁归来，英姿飒爽，故家房魏。","甚是中却有，东山雅量，经纶尽，金华事。","总道丹心为国，要春满、人间桃李。","诗坛风月，清时钟鼓，不妨游戏。","一点台星，五云萦绕，凤池佳气。","为相君满泛，金盘仙露，枕秋蟾醉。"]},{"t":"水龙吟","f":"曲","c":["画楼十日春阴，晚风吹作冰花转。","初冬中候，应时呈瑞，几年未见。","沽酒寻梅，就中此兴，撩人不浅。","更露堂添得，虚窗夜白，清于水，光如练。","我老久谙世味，最欣然、人安米贱。","蝗蝝入地，麦旗掉垄，翠翻平甸。","大犰清边，为民祈谷，睿思何远。","在词臣合取，元和贺例，拜明光殿。"]},{"t":"水龙吟","f":"曲","c":["春流两岸桃花，惊涛极目吞天去。","孤舟缆解，棹歌声沸，渔舠掀舞。","云影西来，片帆吹饱，满空风雨。","怅淋漓元气，江南图画，烟霏尽，汀洲树。","天地此身逆旅，笑归来、满衣尘土。","功名无子，就中多少，艰危辛苦。","北去南来，风波依旧，行人争渡。","听沧浪一曲，渔人歌罢，对夕阳暮。"]},{"t":"水龙吟","f":"曲","c":["凋零万木丛中，秋霜不陨苍筠节。","十年相见，燕南赵北，无根行客。","妻病儿殇，归来空在，蒯缑弹铗。","分躬耕垄□，□山鹊起，谁唤与，将军猎。","腰下铁丝有箭，柰荒寒、冷霾彪穴。","见哀漂母，犹胜低首，看人颜色。","百折弥坚，一穷终泰，不容终结。","望伯奇细写，履霜幽怨，洒西风血。"]},{"t":"水龙吟","f":"曲","c":["汉坛千古风流，笑谈自是诗书将。","两淮草木，一门忠孝，先声远畅。","奕世金貂，雄边韬略，三军独张。","道十年汉水，旌旗动色，春都在，投壶唱。","一点德星回照，光浮动、太山千丈。","戟门春静，人安事简，提封保障。","汉相规随，盖公安靖，平生心赏。","见筹毫不远，凤池消息，醉仙家酿。"]},{"t":"水龙吟","f":"曲","c":["喜看春雨如膏，东风吹作冰花转。","海棠红瘦，梨花香淡，似嫌春晚。","纵使寒生，犹胜空隙，陌尘黄卷。","道佳人拾翠，王孙忆草，都不负，寻芳眼。","欲见太平有象，除丰年、更何可羡。","田家作苦，老臣忧国，眉头俱展。","最好知时，清明前后，一犁非浅。","笑乐天空抱，元和诗律，梦金銮殿。"]},{"t":"水龙吟 寿陈节斋","f":"曲","c":["倚天望汉台高，骞腾便到烟霄上。","一时殊遇，风云俪景，元龙豪爽。","刚断冰清，风流却有，东山雅量。","道十年京洛，棠阴遗爱，人如醉，春风酿。","一点德星回照，光浮动、太行千丈。","戟门春静，人安事简，功余保障。","燕寝香凝，不妨时在，骚坛吟赏。","为使君预泛，凤池春浪，寿金华相。"]},{"t":"水龙吟 送崔中丞赴上都","f":"曲","c":["绿杨一道飞花，绣花乱点如晴雪。","都门几日，翠鸾回畛，情驰魏阙。","顷不忘君，时虽多暇，远犹辰说。","道六条尽备，诸人多样，卒难应，和鸾节。","物胜自余芽蘖，恐多输、豸霜摧折。","人无定志，事随云变，莫扪渠舌。","百步穿杨，空拳搏虎，岂容重发。","望君侯早晚，去登黄阁，作调元客。"]},{"t":"水龙吟 送焦和之赴西夏行省","f":"曲","c":["当年紫禁烟花，相逢恨不知音早。","秋风倦客，一杯情话，为君倾倒。","回首燕山，月明庭树，两枝乌绕。","正情驰魏阙，空书怪事，心胆堕，伤殷浩。","祸福无端倚伏，问古今、几人明了。","沧浪渔父，归来惊笑，灵均枯槁。","邂逅淇南，岁寒独在，故人襟抱。","恨黄尘障尽，西山远目，送斜阳鸟。"]},{"t":"水龙吟 登邯郸丛台","f":"曲","c":["春风赵国台荒，月明几照苕华梦。","纵亡横破，西山留在，翠鬟烟拥。","剑履三千，平原池馆，谁家耕垄。","甚千年事往，野花双塔，依然是，骚人咏。","还忆张陈继起，信侯王、本来无种。","乾坤万里，中原自古，几多麟凤。","一寸囊锥，初无语颖，也沾时用。","对残釭影淡，黄粱饭了，听征车动。"]},{"t":"水龙吟 赋春雪","f":"曲","c":["空斋寂寞春寒，坐来庭竹风声悄。","天低云暖，冰花谁剪，须臾云扰好是东君，与时呈瑞，春回枯槁。","快黄尘厌尽，千林膏沐，休更问，青山老。","我爱春来起早。","恍芸窗、光摇琼岛。","玉华城郭，炊烟巷陌，酒旗风袅。","高兴悠然，沽垆思与，文园倾倒。","为使君预报，春城灯火，比年时好。"]},{"t":"水龙吟 赋秋日红梨花","f":"曲","c":["纤苞淡贮幽香，玲珑轩锁秋阳丽。","仙根借暖，定应不待，荆王翠被。","潇洒轻盈，玉容浑是，金茎露气。","甚西风宛胜，东兰暮雨，空点缀，真妃泪。","谁遣司花妙手，又一番、争奇呈异。","使君高卧，竹亭闲寂，故来相慰。","燕几螺屏，一枝披拂，绣帘风细。","约洗妆快泻，玉瓶芳酒，枕秋蟾醉。"]},{"t":"水龙吟 赋莲花海棠","f":"曲","c":["两株云锦翻空，换根元有丹砂秘。","绣帏重绕，银红高照，故家风味。","翠羽生红，雾纱肌玉，风流谁比。","记沉香亭暖，真妃半醉，云鬓乱，耽春睡。","梦里昆明灰冷，恍留在、红幢翠袂。","金盘华屋，无心与并，朱门桃李。","一盏伤春，临轩便恐，彩鸾交坠。","倩紫箫唤起，霓裳旧曲，拚花前醉。"]},{"t":"水龙吟 赋筝","f":"曲","c":["故家张乐娱宝，乐中无似秦筝大。","华筵听处，一挥银甲，笙竽幽籁。","四座雄声，满空秋雨，来从天外。","甚翛然思变，白翎清调，惊飞下，金莲塞。","长忆桓伊手语，抚哀弦、醉歌悲慨。","使君元有，不凡风调，平生豪迈。","绿酒毹堂，为予翻作，八鸾□海。","道更张正赖，新声陶写，继中书拜。"]},{"t":"水调歌头","f":"曲","c":["汾流浥余润，霜菊满秋香。","酿成一堂和气，来荐老人觞。","七十人生稀有，况复年逾八十，饮啖日康强。","肮脏欲谁与，赵壹倚门旁。","颊浮丹，瞳点漆，鬓如霜。","平生阴有神相，特为表刚肠。","世事语来无味，只有读书一念，老矣不能忘。","九老更添一，图画见高堂。"]},{"t":"水调歌头","f":"曲","c":["一峰华不注，东望雨冥冥。","黄云画角，回首客舍又幽并。","喜按西来佳耗，闻道东山未老，双鬓为谁青。","经济有公论，且莫叹飘零。","杏花吟，山色句，尽称停。","平生风味不浅，聊尔写襟灵。","步冷东垣秋水，坐对汾亭夜月，两地若为情。","合作碧箫曲，留待醉时听。"]},{"t":"水调歌头 为仲方东园赋","f":"曲","c":["野饮不称意，归促紫游缰。","谁知草堂深处，清赏兴尤长。","梦里佳人锦瑟，眼底瓦盆浊酒，衣袖醉淋浪。","歌罢竹轩晚，风细月波凉。","为东园，梅与竹，足清香。","不须更栽桃李，花底驻春光。","人道漆园家世，王谢风流未远，培取桂枝芳。","读书贫亦好，此语试平章。"]},{"t":"水调歌头 次前韵","f":"曲","c":["纫兰缀芳佩，远驾振灵修。","王城似海无际，泛若一轻舟。","谁着朱衣白简，老坐凝床十日，双鹘漫横秋。","落日壮心在，不负鬼神幽。","笑咿嚘，惊肮脏，竟何求。","丈夫出处义在，不用计行留。","万事味来嚼蜡，只有济时一念，未肯死前休。","驱马出东郭，聊以散吾忧。"]},{"t":"水调歌头 寿时相","f":"曲","c":["佩兰近佳节，高第照神州。","西山致有爽气，天际翠眉修。","酿作碧霄清露，暗满庭前细菊，香淡一帘秋。","春酒未容泻，寿席已风流。","锵鸣玉，看独步，凤池头。","荐贤真宰事业，药笼到兼收。","总道平生襟量，一片丹衷为国，不负幕中筹。","齐浣救时语，持用寿君侯。"]},{"t":"水调歌头 寿雪斋","f":"曲","c":["高斋际晴雪，万象入遐观。","文章在公余事，闻望到欧韩。","千古微茫洙泗，浩浩发源伊洛，百折障狂澜。","歌咏武公志，儆折过铭盘。","济时心，调鼎手，未容闲。","重看印窠，垂锦花底压千官。","风说梅梢春信，一夜蜡痕香满，光动寿杯宽。","勋业鼎钟上，留待百年看。"]},{"t":"水调歌头 和姚雪齐韵","f":"曲","c":["书史有真味，谁遣博微官。","丈夫出处道在，义命正须安。","浩浩都门冠盖，眼冷鸡虫得失，矫首入遐观。","时对雪斋老，清议豁襟颜。","阅名书，探理窟，惊铭盘。","自叹空然鼠腹，过饮不知繁。","万古乾坤清气，散人诗仙脾鬲，挥洒有余欢。","早晚付心诀，风雨满堂寒。"]},{"t":"水调歌头 和赵明叔韵","f":"曲","c":["西山卷残雨，天宇翠眉修。","余霞渐成绮散，楼外月如舟。","漾漾银河垂地，浩浩天风拂枕，吹满一帘秋。","觉我清兴远，归梦到岩幽。","野猿惊，山鸟笑，欲何求。","十年一官黄散，了不到封侯。","自有竹林佳处，满酌洼尊贮酒，一醉共浮休。","夔契在廊庙，畎亩不须忧。"]},{"t":"水调歌头 送王子初之太原","f":"曲","c":["将军报书切，高卧起螭蟠。","悲欢离合常事，知己古为难。","忆昔草庐人去，郁郁风云英气，千载到君还。","歌吹展江底，长鲜铗不须弹。","路漫漫，天渺渺，与翩翩。","西风鸿鹄，一举横绝碧云端。","自笑鹡鸰孤影，落日野烟原上，沙晚不胜寒。","后夜一相意，明月满江干。"]},{"t":"水调歌头 送王修甫东还","f":"曲","c":["樊川吾所爱，老我莫能俦。","二年鞍马淇上，来往更风流。","梦里池塘春草，却被鸣禽呼觉，柳暗水边楼。","浩荡故园思，汶水日悠悠。","洛阳花，梁苑月，苦迟留。","半生许与词伯，不负壮年游。","我亦布衣游子，久欲观光齐鲁，羁绁在鹰韛、早晚西湖上，同醉木兰舟。"]},{"t":"水调歌头 宴张右丞遂初园","f":"曲","c":["园林足佳胜，钟鼓乐时康。","去天尺五韦杜，此日汉金张。","谁似主人好客，暂趁金华少暇，尊俎共徜徉。","三馆尽英隽，簪履玉生光。","眺东台，登北榭，宴南堂。","露凉玉簪零乱，竹静有深香。","醉听新声金缕，爱仰东山雅量，清赏兴何长。","高咏遂初赋，松柏郁苍苍。"]},{"t":"风入松 观灯下半开杏花","f":"曲","c":["一枝浓艳照华堂。","暖蕊贮春光。","写生莫羡徐熙笔，风流在、百子池傍。","点缀红妆玉颊，帘苫粉淡宫妆。","静怜疏影伴昏黄。","添麝入炉香。","惜花人老情缘在，云屏晚、银烛高张。","细泻一杯春露，浩歌微雨东墙。"]},{"t":"玉楼春 冬至夜侍祭","f":"七言律诗","c":["阴消阳长从今数。","除客归来闻好语。","月明满地紫烟生，暖人刺文添绣缕。","冷风肃肃生庭户。","桂酒光清摇燕俎。","今冬记我致严时，爆竹声中听五鼓。"]},{"t":"玉漏迟","f":"曲","c":["越山征路杳。","东南淡淡，长空飞鸟。","俪影同翻，明月一枝乌绕。","共道有心避事，甚未若、从渠相调。","君莫笑。","南楼苦要，胡床舒啸。","空扰。","画里江山，总轮与风流，眼中年少。","也学凝儿，官事几时能了。","一曲骊歌未动，还梦到、三山晴照。","江月晓。","莫为赏音稀少。"]},{"t":"玉漏迟 留别淇上诸君","f":"曲","c":["浙江江路杳。","苍茫自叹，南飞鸟鸟。","故国回头，梦里青山吟绕。","手把一麾南去，道不比、八州常调。","君莫笑。","南楼苦要，胡床舒啸。","休扰。","归去扁舟，若比似陶朱，尚犹年少。","飞泳虽殊，友义固应明了。","拟览九江秀色，谁凄断、关河残照。","霜月晓。","去去眼中人少。"]},{"t":"玉漏迟 答南乐令周干臣来篇","f":"曲","c":["竹林幽思杳。","栖迟自叹，离群孤鸟。","万里云翔，海树去相依绕。","邻笛一声唤起，忆共听、朱丝雅调。","还自笑。","当年已愧，孙登清啸。","清扰。","回首分飞，怅落落相期，望高崧少。","会鲜离多，经世又谁曾了。","二子况成陈迹，落月满、屋梁空照。","庭户晓。","得意眼中人少。"]},{"t":"夺锦标","f":"曲","c":["六郡雄藩，会稽旁带，雨浙风烟如昔。","碧草莫伤春浦，冠盖东南，几多行客。","正新亭父老，望云霓、苦思休息。","道朝家、雨露同春，问甚江南江北。","贺监归舟逸兴，何似双旌，尽慰元郎行色。","镜水绿通朱阁，威畅恩宣，海波春寂。","笑东山老去。","此心初、非□泉石。","约海楼、翡翠同游，醉里山阴陈迹。"]},{"t":"好事近","f":"曲","c":["宫殿曲江头，漠漠轻阴开彻。","花柳都城三月，正禁烟时节。","阿鸣毂击玉泉游，故老向人说。","一片春风箫鼓，荡黎花香雪。"]},{"t":"好事近","f":"曲","c":["华发一衰翁，世事眼中看彻。","只为年来薄宦，负东山高节。","冥冥神理到无凭，此外更何说。","安得百壶春酒，埽羁愁如雪。"]},{"t":"好事近 过南云门","f":"曲","c":["南北两云门，竹圃稻畦如画。","罢亚黄云万顷，自长渠飞洒。","太行钟秀尽三乡，形胜递高下。","笑我年来用舍，似田间秧马。"]},{"t":"好事近 尝点东坡桔乐汤作","f":"曲","c":["石鼎响松风，茗饮老来多怯。","唤起雪堂清兴，瀹鹧斑金屑。","橘中有乐胜商山，香味不容说。","觉我胸中磈磊，被春江澄彻。"]},{"t":"好事近 春寒继刘君卿韵三首","f":"曲","c":["斗柄转春城，向暖小桃开彻。","不似今年正月，过深冬时节。","故将新巧发阴机，春事未容说。","且就驱云风帚，埽西山晴雪。"]},{"t":"好事近 赋庭下新开梨花","f":"曲","c":["轩锁碧玲珑，好雨初晴三月。","放出暖烟迟日，醉风檐香雪。","一尊吟绕洗妆看，玉笛笑吹裂。","留待夜深庭院，伴素娥清绝。"]},{"t":"如梦令","f":"曲","c":["老境心便多暇。","束缚尘缨高挂。","饭饱去寻君，闲步闲吟闲话。","闲话。","闲话。","过眼纷华都罢。"]},{"t":"如梦令","f":"曲","c":["半世随波从众。","几被狙翁调弄。","富贵苦相谩，一枕槐根春梦。","春梦。","春梦。","况复此身无用。"]},{"t":"如梦令","f":"曲","c":["友道雨翻云覆。","胶漆几人持久。","遣兴漫题诗，客至有钱沽酒。","沽酒。","沽酒。","径入醉乡无有。"]},{"t":"如梦令 和曲山韵","f":"曲","c":["仁宦须求遭遇。","不顾已沾泥絮。","攘攘世间人，总被虚名引去。","引去。","引去。","光景促于朝暮。"]},{"t":"江城子","f":"曲","c":["小窗遥夜失冬严。","觉春添。","卷疏帘。","掌许冰花，撩乱扑风檐。","喜倒坐中儿子辈，争指似，谢家盐。","一杯灯下醉掀髯。","处穷阎。","最情忺。","万垄含春，江上麦纤纤。","应笑冻吟苏老子，揩病目，认青帘。"]},{"t":"江城子 为张同知寿","f":"曲","c":["滦江晴漾首山前。","玉为渊。","秀相连。","总把华英，都付使君贤。","梅竹堂深歌吹动，香似雾，酒如川。","列城千里听鸣弦。","颂声喧。","觉春偏。","争遣翱翔，犹是贰车权。","满泛一杯添寿酒，悬斗印，看他年。"]},{"t":"江城子 赋拜月图","f":"曲","c":["一枝繁杏宋墙东。","翠帷重。","卷春风。","留得残妆，帘月拜玲珑。","云作鬓蝉霞作袂，香雾湿，玉鬟松。","闲情都付烛华红。","琐窗中。","照芳容。","细逐行云，零乱紫金峰。","天外翠鸾仙侣在，城阙晚，梦芙蓉。"]},{"t":"行香子","f":"曲","c":["秋霁遥岑。","何处登临。","水西头、来散闲心。","绕园细履，栽种成阴。","□拈秋香，浮酒碗，入孤斟。","老境骎骎。","乡社浮沉。","醉颜酡、白发盈簪。","夕阳归路，听我长吟。","待野梅芳，多载酒，再相寻。"]},{"t":"西江月","f":"曲","c":["社鼓惊飞梨雪，村箫吹破桑芽。","清明野饮见田家。","老叟邀予下马。","劝饮一卮芳酒，绕看满树幽花。","杯盘草草乐年华。","不弃同来观化。"]},{"t":"西江月","f":"曲","c":["散策暂辞凫吏，倚楼来听渔歌。","夕阳西下乱山多。","白鸟苍烟冲破。","一夜朔风吹雪，白云飞满长河。","不将幽梦付凌波。","意在吴郎画舸。"]},{"t":"西江月 寿王中丞","f":"曲","c":["梅萼暗传春信，菊枝尽傲霜威。","风姿元与岁寒期。","况是小春天气。","翠实调羹未晚，秋香添寿多宜。","高名北海旧蟠螭。","未似东山雅意。"]},{"t":"西江月 寿李彦祥","f":"曲","c":["近岁忆游竹里，今年来遇生朝。","平生洒落邑中豪。","邂逅风神不老。","赏尽山阳烟景，去翻亳海云涛。","太行晴色任秋高。","人与黄花长好。"]},{"t":"西江月 间步州南古堤","f":"曲","c":["返照斜明双塔，乱山回绕孤城。","年来风物似升平。","人说三王善政。","世事正宜静待，田园好去躬耕。","云闲归鸟有遗声。","唤起投林高兴。"]},{"t":"西江月 继张孝纯韵","f":"曲","c":["郢下空歌白雪，琴中谁听高山。","人生何用钉疏顽。","不过两盂日饭。","梦到钓台老树，秋风闲煞渔竿。","沙鸥无数点江干。","知我忘机去慢。"]},{"t":"西江月 赠张子文","f":"曲","c":["联辔闲谈诗雅，停杯高咏晁词。","山城投宿晚凉时。","邂逅青云公子。","濯锦江边相忆，鸣条山下分携。","秋风摇荡菊花期。","伫候翩翩归骑。"]},{"t":"青玉案 赋紫金沙","f":"曲","c":["绿阴暗尽西城树。","人总道、春归去，袅袅柔条高几许。","绛灯闪烁，翠云萦护。","元有留春处。","金尊未厌倾芳醑。","醉墨题诗要香露。","蝴蝶飞来何栩栩。","向人有意，绕阑翻舞。","似约花闲住。"]},{"t":"临江仙","f":"曲","c":["昨日举杯亲饯别，六人吟啸呵呵。","今朝丹旐扬城阿。","一棺零落恨，都付逝川波。","万事转头真是梦，两轮来往如梭。","人生百岁合如何。","放开眉上锁，得酒且高歌。"]},{"t":"临江仙 为曲山作","f":"曲","c":["别墅寒梅方入梦，多君来报花期。","野塘流水小桥西。","南枝香烂漫，却恨赏音稀。","正有玉堂人最爱，垂垂两鬓如丝。","和羹心事未应迟。","金尊重醉倒，且莫晚风吹。"]},{"t":"临江仙 寿李节使","f":"曲","c":["柱石中朝黄阁相，河山千古南州。","多君谈笑觅封侯。","朱轮翻皂盖，锦带佩吴钩。","满府治声歌五裤，稍稍俊气横秋。","今年寿席更风流。","青云新甲第，一笑醉金瓯。"]},{"t":"临江仙 送治中李公","f":"曲","c":["天一云衣无定态，眼中时事休惊。","年来钟鼎到书生。","一麾仍出守，五马看专城。","千古金陵佳丽地，中郎素有先声。","一江春浪暮烟平。","此身眠食外，万事总虚名。"]},{"t":"南乡子","f":"曲","c":["溪水净滩沙。","紫动林梢半是花。","长日马蹄闲信步，谁家。","晓入南园到晚霞。","时事闹蜂衙。","一片闲心逐去鸦。","烂醉玉瓶沙上酒，生涯。","过眼浮云不足夸。"]},{"t":"南乡子","f":"曲","c":["青琐汉中郎。","满袖长携玉案香。","记得赋诗横槊日，临江。","气压风涛一苇航。","莲炬晚分光。","谏疏回天豸有霜。","七十平头从此数，称觞。","滹水渊源庆未央。"]},{"t":"南乡子","f":"曲","c":["人物旧温郎。","心事珠帘月床。","笑里玉台重藉手，谁量。","折得杨枝恼孟光。","得鲤岂思鲂。","老境其如伯道伤。","但愿维罴应汝梦，称觞。","趁取春风慰北堂。"]},{"t":"南乡子","f":"曲","c":["万汇帝城春。","况是明时选用人。","爱煞曲山周老子，依仁。","任运□□不自论。","六任漫逢辰。","甚是荣华尽苦辛。","赢得归来儿女笑，苏秦。","白马红缨衫色新。"]},{"t":"南乡子","f":"曲","c":["帘影静棋枰。","平野风来分外清。","一带好山供望眼，云屏。","落日烟霏翠满亭。","世事不须惊。","底用相逢话独醒。","常使玉瓶沙上酒，如渑。","杖履时来月下倾。"]},{"t":"南乡子","f":"曲","c":["一雪静林皋。","冷压浮阳气不骄。","菜甲榆椒浑不动，寂寥。","赚得轻黄上柳条。","诗思苦相撩。","酒盏新来顿绝交。","连夜客窗寒似水，无憀。","谁约春风锁绮寮。"]},{"t":"南乡子","f":"曲","c":["乔木色苍苍。","山顶难留落日光。","灯影碧流深几许，浮觞。","来醉张家第四场。","世事莫论量。","相对尊前两鬓霜。","富贵几时当适意，杯长。","问甚春星带草堂。"]},{"t":"春从天上来","f":"曲","c":["罗绮深宫。","记紫袖双垂，当日昭容。","锦对香重，彤管春融。","帝座一点云红。","正台门事简，更捷奏、清昼相同。","听钧天，侍瀛池内宴，长乐歌钟。","回头五云双阙，恍天上繁华，玉殿珠栊。","白发归来，昆明灰冷，十年一梦无踪。","写杜娘哀怨，和泪把、弹与孤鸿。","淡长空。","看五陵何似，无树秋风。"]},{"t":"点绛唇","f":"曲","c":["晴倚层阑，飘飘醉上青鸾背。","飞云崩坠。","万叠银涛碎。","青嶂白波，非复人间世。","人怀霁。","夕阳有意。","返照千山外。"]},{"t":"点绛唇","f":"曲","c":["春雨如膏，最怜适与清明遇。","晚晴庭宇。","画出樊川赋。","冉冉行云，低拂垂杨度。","春如许。","乱花深处。","几点蔷薇露。"]},{"t":"点绛唇 为房祖母寿","f":"曲","c":["婺女呈祥，瑞光分自云衢烂。","凤萱金灿。","留待佳辰绽。","林下丰容，闺壶瞻仪范。","香萦篆。","玉颜如练。","岁岁长康健。"]},{"t":"点绛唇 为承旨唐寿卿寿","f":"曲","c":["秋气平分，郁葱都作充闾喜。","玉堂风味。","磊落青云器。","醉墨乌丝，绿绮传湘水。","千秋岁。","月波如洗。","长照金尊里。"]},{"t":"点绛唇 西湾即事","f":"曲","c":["碧玉环深，一尊同醉清明后。","绿阴晴昼。","多少闲花柳。","身世虚舟，日月惊跳走。","谁豪右。","忘怀惟有。","拍泛船中酒。"]},{"t":"点绛唇 寿周干臣","f":"曲","c":["千古诗坛，苦吟谁得风骚妙。","羡君才调。","一蹴无边徼。","岁岁中秋，喜见朱颜好。","霜蟾皎。","一尊倾倒。","万事秋毫小。"]},{"t":"点绛唇 寿周干臣","f":"曲","c":["秋气平分，画阑桂树秋香底。","良辰美景，拚取花前醉。","彭寿添君，白也诗堪拟。","高歌起。","月波如水。","长照金尊里。"]},{"t":"点绛唇 寿涿郡房二尊亲","f":"曲","c":["露影庭萱，一枝金绽钗头凤。","宝花香供。","寿席光浮动。","懿范闺门，姻族同推重。","琼杯捧。","二亲安宠。","共醉玻璃瓮。"]},{"t":"点绛唇 雨中故人相过","f":"曲","c":["谁惜幽居，故人相过还晤语。","话余联步。","来看花成趣。","春雨霏微，吹湿闲庭户。","香如雾。","约君少住。","读了离骚去。"]},{"t":"点绛唇 雨宵即事","f":"曲","c":["春雨空蒙，晚来点缀闲庭景。","一床灯影。","润入琴丝冷。","清夜沉沉，谁慰孤怀耿。","云生鼎。","倚窗高咏。","爱此春宵永。"]},{"t":"点绛唇 春夜喜雨","f":"曲","c":["好雨知时，万金欲买初无价。","种花才罢。","似为芳枝下。","花重宫城，好个风人雅。","从飘洒。","探花走马。","明日春如画。"]},{"t":"点绛唇 春雨后小桃","f":"曲","c":["端正楼空，一枝春色谁偷得。","夜来消息。","暮雨胭脂湿。","倚竹佳人，翠袖娇无力。","须相觅。","一尊休惜。","转首春狼藉。"]},{"t":"点绛唇 癸酉夏六月五日同河中府官宴白楼","f":"曲","c":["倚槛清歌，一声高遏行云住。","长河倾注。","不煞曦轮暑。","燕寝清香，画栋珠帘雨。","人何处。","一尊绿醑。","满眼青山暮。"]},{"t":"点绛唇 送董彦才西上","f":"曲","c":["杨柳青青，玉门关外三千里。","秦山渭水。","未是消魂地。","坦卧东床，恐减风云气。","功名际。","愿君着意。","莫揾春闺泪。"]},{"t":"点绛唇 探花","f":"曲","c":["春雨添花，绕阑来看花开否。","海棠红瘦。","绿叶花如豆。","梨雪生香，近在清明候。","花为友。","莫轻孤负。","预问邻家酒。"]},{"t":"点绛唇 喜芍药发芽","f":"曲","c":["红叶当阶，朝来拨土红芽秀。","画阑晴昼。","凭暖佳人袖。","一粒丹砂，谁点仙根透。","从今后。","为渠酿酒。","去作花间友。"]},{"t":"点绛唇 题绛州花萼堂时大暑回自河中","f":"曲","c":["一榻清风，故山邂逅欣相遇。","绿阴池树。","荡漾瑶翻处。","赤日红尘，前日中条路。","人良苦。","壮心如故。","快叱王阳驭。"]},{"t":"浣溪沙","f":"七言古诗","c":["纸帐梅花夜色清。","行云香湿堕银屏。","惜花人老若为情。","对酒当歌须适意，凌烟图象是虚名。","千年编简几人青。"]},{"t":"浣溪沙","f":"七言古诗","c":["旅馆灯青夜色曛。","据床谈剧作春温。","胸中云梦入雄吞。","清议素高乌府月，秋霜低厌涨江云。","吴山山下惜轻分。"]},{"t":"浣溪沙","f":"七言古诗","c":["绿树连村际碧山。","春风吹水涨黄湾。","沙汀苹满钓舟间。","薄宦崎岖清议里，风烟吞吐画图间。","夕阳明处鸟飞还。"]},{"t":"浣溪沙","f":"七言古诗","c":["露榻风帘烛影摇。","故人留话慰萧条。","徘徊花月可怜宵。","天淡有云空漠漠，月明无雨更翛翛。","洞天归路踏琼瑶。"]},{"t":"浣溪沙","f":"七言古诗","c":["月色都输此夜看。","人心偏处即多悭。","碧云吹恨满瑶天。","尽着冰壶凉世界，故将阴巧妒婵娟。","桂香和露温幽弹。"]},{"t":"浣溪沙","f":"七言古诗","c":["梅点冰梢蜡蒂凝。","兰芽珠树斗鲜明。","团栾香火此时情。","避世远惭金马客，现山人道老人星。","雪边岩桧尽青青。"]},{"t":"浣溪沙","f":"七言古诗","c":["隋末唐初与汉亡。","干戈此际最抢攘。","一时人物尽鹰扬。","褒鄂有灵毛发动，曹刘无敌简书光。","争教含泣到分香。"]},{"t":"浣溪沙","f":"七言古诗","c":["珍品无多百和浓。","露沾婆律湿兰丛。","喜分新供到南丰。","螺甲未融金雀饼，芳菲已梦碧湘宫。","宝猊先障绣帘风。"]},{"t":"浣溪沙","f":"七言古诗","c":["雨点鸣铙裂竹声。","并随牙板一时停。","词源都作建瓴倾。","白羽挥开诸葛阵，苍涛翻动宪王陵。","低空知有彩云横。"]},{"t":"浣溪沙","f":"七言古诗","c":["雨势苍山共一云。","雨声作气张三军。","秋风亭下叶缤纷。","官事何忧严限促，天心不负老农勤。","夜窗孤客尽先闻。"]},{"t":"浣溪沙 内黄道中","f":"七言古诗","c":["风柳婆娑半亩阴。","两枝巧与道相邻。","树头幽鸟似知音。","马上行人思困睡，天边赤日欲流金。","解鞍休惜濯烦襟。"]},{"t":"浣溪沙 付高彦卿","f":"七言古诗","c":["红翠丛中样度新。","桃花扇影驻行云。","隋唐嘉话阅来真。","一片锦帆浮汴水，两京花柳暗风尘。","彩声会动凤城春。"]},{"t":"浣溪沙 寿王子初","f":"七言古诗","c":["六合澄清到一家。","颙颙文物望中华。","未容诗礼养兰芽。","松柏后雕元有待，圭璋涵润本无瑕。","诰恩行堕五云花。"]},{"t":"浣溪沙 寿汤总管","f":"七言古诗","c":["十载烟花紫紫游。","嘉谟曾补翠云裘。","归来尤荷宠光优。","画戟清香高北里，虎符金节照南州。","寿波无惜卷吟瓯。"]},{"t":"浣溪沙 寿李卫尉","f":"七言古诗","c":["矍铄当年汉伏波。","紫微垣外待雕戈。","笑骑天驷下天河。","华发雅宜麟阁画，春风先送武城歌。","朱颜休惜卷金荷。"]},{"t":"浣溪沙 寿周干臣","f":"七言古诗","c":["十载相期紫禁游。","一官谁想客西州。","春风闲倚仲宣楼。","四海论交真益友，一年好处是中秋。","寿波无惜卷金瓯。"]},{"t":"浣溪沙 张右丞寿","f":"七言古诗","c":["补衮功深浴凤池。","好贤人道似缁衣。","佩声清音见委蛇。","千岁寿祺阴有积，两宫恩眷古来稀。","东山歌酒乐时熙。"]},{"t":"浣溪沙 客亭观涨","f":"七言古诗","c":["老雨长河壮怒涛。","客亭夜久听喧号。","平明两涘渺江皋。","沙尾没来渔箔短，危樯看处客帆高。","斜阳汀草乱青袍。"]},{"t":"浣溪沙 送王子勉都运关中","f":"七言古诗","c":["蓟北分携已六年。","秋风淇上又离筵。","一尊情话重留连。","内史调兵惟汉相，春潭通漕笑韦坚。","岳云抛翠上吟鞭。"]},{"t":"浣溪沙 送刘仲元赴平定州亲迎","f":"七言古诗","c":["青鸟西传燕尔期。","乘龙喜气见修眉。","芳悰浓似去年时。","禁脔名香天盼重，玉台春暖镜鸾栖。","人生乐处是新知。"]},{"t":"浣溪沙 赋筝","f":"七言古诗","c":["朋盍华簪醉未沾。","主人张乐见厌厌。","一声银甲裂霜缣。","涧水咽冰翻陇怨，将军出塞忆蒙恬。","碧桃花底玉笙惉。"]},{"t":"浣溪沙 题韩氏别墅","f":"七言古诗","c":["翠竹连村映白沙。","小冈回抱一川斜。","旋开幽沼听鸣蛙。","樵客局边惊橘乐，黄尘门外任蜂衙。","树头山色晚来佳。"]},{"t":"浣溪沙 赠朱帘绣","f":"七言古诗","c":["满意苕华照乐棚。","绿云红滟逐春生。","卷帘一顾未忘情。","丝竹东山如有约，烟花南部旧知名。","秋风吹醒惜离声。"]},{"t":"望月婆罗门引","f":"曲","c":["河山清眺，风烟两戒见殷都。","唐津浩浩舟车。","一水东浮沧海，宝带束燕吴。","更中州雄跨，奇货堪居。","平生壮图。","笑到此、反区区。","正似齐门抱瑟，不解吹竽。","视吾耿耿，道玉佩、或能利走趋。","如不尔、归老樵渔。"]},{"t":"望月婆罗门引","f":"曲","c":["小窗人静，梅枝香细月华明。","博山一缕云蒸。","好个臞仙风骨，诗思苦凭陵。","有间书遮眼，敧枕松声。","素无宦情。","较得失、一毫轻。","自叹高歌白雪，寡和谁听。","潇然巾卷，见芝宇、光浮寿颊生。","春酒绿、何碍频倾。"]},{"t":"望月婆罗门引","f":"曲","c":["星屯落落，当年旌旆拥雍丘。","西风腾踏清秋。","回首黄云画角，吹断夕阳楼。","且杯倾竹叶，歌戛吴钩。","功名浪求。","枉敝尽、黑貂裘。","重恨人生无定，长负欢游。","燕鸿南去，怅秋水、秋烟总是愁。","江浦晚、稳宿汀洲。"]},{"t":"望月婆罗门引","f":"曲","c":["去年元夕，飘零书剑大梁城。","春风九市花灯。","尚忆东楼行乐，谈笑故人情。","对一尊芳酒，满意歌声。","今年可能。","人与境、两竛竮。","寂寞黄昏陌巷，戎鼓断人行。","梅花归梦，正一笑、柴门稚子迎。","庭树鹊、何苦频惊。"]},{"t":"望月婆罗门引 中秋夜","f":"曲","c":["柳边层榭，倚兰人共月孤高。","乱云脱坏崩涛。","一片广寒宫殿，桂影数秋毫。","尽掀髯老子，露湿宫袍。","人生此朝。","能几度、可怜宵。","况对清尊皓齿，舞袖织腰。","碧空如洗，拚一醉、河倾转斗杓。","今夕乐、归梦临皋。"]},{"t":"望月婆罗门引 为吹头管张解愁赋","f":"曲","c":["秋怀索寞，悠悠心事野鸥边。","几回崔九堂前。","照眼故家风调，人物尚依然。","按清商一曲，倾动华筵。","新声巧翻。","道且莫、诧贞元。","爱煞珠绳银管，满意清圆。","风花无梦，待回施、春光与少年。","杜陵老、凄断邻船。"]},{"t":"望月婆罗门引 春雪后看山","f":"曲","c":["太行晴霁，孤墉高处揖清寒。","云闲万髻千鬟。","底事春风面目，一变玉巑岏。","淡夕阳平远，野鸟飞还。","青云莫攀。","吾高兴、在东山。","偃蹇孤松丘壑，不碍春悭。","背阴桃李，正藉得、春光亦强颜。","长剑铗、且莫轻弹。"]},{"t":"望海潮","f":"曲","c":["龙沙王气，恒山秀色，德星光动南州。","使君高宴，北山佳处，薰风红闪旗旒。","两翼拥貔貅。","骇鼍鸣叠鼓，杖奋惊虬。","一点星飞，画柱得意过边筹。","貂蝉元自兜鍪。","笑阎阎小子，谈笑对侯。","万骑平原，千艘汉水，堂堂小试清油。","宾从尽风流。","喜武同张肄，书漫韩投。","乐事更酬。","醉魂还梦菊花秋。"]},{"t":"望海潮 为子初总管寿","f":"曲","c":["桐乡遗爱，于门阴积，充闾气自葱葱。","霜华对菊，橙金泛醁，秋香吹满帘栊。","人物汉元龙。","喜升堂一拜，今几相同。","洗尽金貂，贵气黄卷贮深功。","见君雅量雍容。","信男儿到此，方是豪雄。","林下夫人，膝前文度，摩挲湖玉双峰。","福寿尽无穷。","看一家乐事，五县提封。","彩袖歌钟。","年年长醉玳筵红。"]},{"t":"望海潮 为故相云叟公寿","f":"曲","c":["炬明珂马，戟森兵卫，日长铃阁春凝。","舜朝仪凤，傅岩霖雨，世传昂宿储精。","天地入经纶。","见东山高卧，一念苍生。","谈笑金华，故事六合海波平。","一杯福寿川增。","请大人静听，贱子微诚。","苏岭云霞，西溪梅竹，风烟画出共城。","羽翼汉功成。","尽山中名在，天外鸿冥。","一点台星。","清光长射老人明。"]},{"t":"眼儿媚","f":"曲","c":["满帘夜月耿霜秋。","云梦黯歌楼。","残灯伴晓，夕阳催暮，海水添愁。","天涯地角相思恨，谁道北生休。","一篇照映，唐人诗雅，千古风流。"]},{"t":"眼儿媚","f":"曲","c":["我来吊古过悲秋。","徙倚夕阳楼。","画堂歌舞，都能几日，何限幽愁。","合欢床冷孤眠苦，争向死前休。","凭阑闲看，一双鸂鶒，对起中流。"]},{"t":"眼儿媚","f":"曲","c":["西风归燕几经秋。","人老水边楼。","一灯孤枕，满襟清血，花也含愁。","前堂歌吹新声有，争似去来休。","长河若解，将姝遗恨，与泪俱流。"]},{"t":"眼儿媚 呈周干臣","f":"曲","c":["桑榆晚景日骎骎。","莫厌数相寻。","静怜幽境，闲谈情话，与涤烦襟。","济时幸有诸公在，乡社好浮沉。","闲云却恐，西风吹去，认做商霖。"]},{"t":"眼儿媚 赋燕子楼用干臣继路宣叔乐府韵","f":"曲","c":["横塘烟淡冷涵秋。","寂寞旧妆楼。","珠帘夜月，露桃幽怨，总是闲愁。","形消骨化情缘在，此恨若为休。","长河解浣，佳人无那，倒卷黄流。"]},{"t":"喜迁莺","f":"曲","c":["五更残梦。","听绿窗莺语，罗衾香拥。","百啭多情，娇啼无泪，枕上一声时送。","真成翠鬟双笋，当户玉琴初弄。","欲谁共。","趁风和求友，乔林烟蓊。","春动。","花气重。","暗度垂杨，暖人酴醾洞。","倦客芳悰。","佳人幽思，愁满彩笺金凰。","自怜比来心事，两翅果谁搏控。","听指纵。","望高城落日，黄尘飞鞚。"]},{"t":"喜迁莺","f":"曲","c":["秋怀谁写，听一声金缕，同倾芳酒。","娇啭林莺，圆累珠串，春在碧罗云袖。","宫中磬簧齐发，字外五音何浏。","坐闲友。","道江南风月，此声无有。","回首。","伤离久。","三叠阳关，不到青青柳。","得意石州，片帆云影，翻动海山明秀。","风流故家未减，自笑杜陵衰叟。","再相遘。","卷中人正好，崔徽消瘦。"]},{"t":"黑漆弩","f":"曲","c":["苍波万顷孤岑矗。","是一片、水面上天竺。","金鳌头、满咽三杯，吸尽江山浓绿。","蛟龙恐下然犀，风起浪翻如屋。","任夕阳、归棹纵横，待偿我、平生不足。"]},{"t":"黑漆弩","f":"曲","c":["休官彭泽居闲久。","纵清苦、爱吾子能守。","幸年来、所事消磨，只有苦吟甘酒。","平生道在初心，富贵浮云何有。","恐此身、未许投闲，又待看、凤麟飞走。"]},{"t":"感皇恩","f":"曲","c":["佳节近中秋，秋霖晴快。","飞净残云碧空大。","金波穆穆，掩尽玉绳光彩。","坐来风露冷、青冥外。","世运难前，儒冠何赖。","四壁相如到沽卖。","纷纷过眼，多少时情物态。","杳然清梦去、桴沧海。"]},{"t":"感皇恩","f":"曲","c":["今夕是何年，故人相遇。","快着银杯泻春露。","高阳旧友，要听一声金缕。","行云留不去、惊如许。","凤喙微吟，珠绳低度。","夜半银屏恍私语。","夜花零乱，掩尽六朝琼树。","明朝南浦道、伤平楚。"]},{"t":"感皇恩","f":"曲","c":["少日竹林游，凤麟飞走。","一段江山最英秀。","南衙倾盖，满院桐阴清昼。","鬓华思此际、浑依旧。","云梦心胸，文章山斗。","好个经纶玉堂手。","婆娑桂影，凉人露盘仙酎。","一杯先领取、乔松寿。"]},{"t":"感皇恩","f":"曲","c":["回首竹林游，山阴陈迹。","洒落襟期记畴昔。","论文把酒，醉尽清泉白石。","几年江海上、空相忆。","邂逅淇南，羁愁都释。","两鬓怜君更如漆。","幽怀重叙，不待小槽红滴。","新诗随欬唾、骊珠湿。"]},{"t":"感皇恩","f":"曲","c":["日日午餐余，即须幽讨。","拄杖长行觅周老。","三杯两盏，不致玉山倾倒。","与君何处去、乾冈好。","松影闲庭，长吟藉草。","白发多来故人少。","春山何在，两树寒梅枯槁。","一声邻笛起、催归早。"]},{"t":"感皇恩","f":"曲","c":["风雨暗公堂，故人晤对。","邂逅燕城又三载。","偶因官事，喜向广平重会。","照人光彩好、心期在。","万里功名，半生湖海。","十五年间颜改。","笑谈尊俎，比老几回倾盖。","秋风横漯上、期相待。"]},{"t":"感皇恩","f":"曲","c":["节序四时闲，功成还退。","此事君侯与心会。","幽亭高卧，眼冷画堂金翠。","越装都付与、诸郎辈。","虎帐筹边，锦鞯歌凯。","惨淡风云梦江海。","大绍挂壁，小隐一枝松盖。","清闲人道胜、中书拜。"]},{"t":"感皇恩","f":"曲","c":["浓绿涨千林，征鞍东去。","十日祁阳为君住。","几回清唱，飞尽海棠红雨。","人生当适意、何良苦。","簿领公堂，风沙长路。","赢得佳人怨迟暮。","沙头酒尽，犹惜玉鞭轻举。","一声声不断、歌金缕。"]},{"t":"感皇恩","f":"曲","c":["书叶散芸香，牙签无数。","案上藜羹当膏乳。","地偏心远，日与圣贤晤语。","市声飞不到、横披处。","一炷龙涎，满瓯春露。","旋埽幽轩约宝住。","清谈有味，总是故家风度。","子云亭户好、龙津路。"]},{"t":"感皇恩","f":"曲","c":["流水小桥横，冶头沙路。","一道清阴转林坞。","满襟凉润，犹是夜来新雨。","幽禽忺客至、如晤语。","坐荫辛夷，间挥吟尘。","泽畔行歌恐良苦。","人生适意，正要时情容与。","却怜身处世、初无补。"]},{"t":"感皇恩","f":"曲","c":["灯火夜阑珊，故人相对。","忘尽南窗引书睡。","情谈亹亹，时带少年风味。","门前霜月炯、停吟辔。","湖海相望，金兰交契。","白发中年能几会。","明朝赵北，又是摇摇风旆。","一杯还到手、休辞醉。"]},{"t":"感皇恩","f":"曲","c":["叠嶂际清江，枫林辉映。","潮落波平镜光静。","六朝兴废，都付渔郎烟艇。","莼鲈香正美、秋风冷。","笳鼓归来，风云增胜。","梦里无烦想幽景。","风流公子，写出五湖高兴。","画中还领取、江山影。"]},{"t":"感皇恩","f":"曲","c":["暴下晋州城，茫然心曲。","卧对风轩数竿竹。","暑光不受，似我腰围□束。","病机还自忖、非寒燠。","力仕难任，居头不足。","风雨忧愁更相促。","星星鬓影，中有利名千斛。","省来都外物、真蛮触。"]},{"t":"感皇恩","f":"曲","c":["十里走徵车，笑予游宦。","老马为驹望英盼。","客怀相慰，时对凌烟生面。","浩歌虽慷慨、南山粲。","公子翩翩，沉酣经传。","不似当年闭门衍。","杨花归路，肯逐东风流转。","且遮西日去、长安远。"]},{"t":"感皇恩 与客读辛殿撰乐府全集","f":"曲","c":["幽思耿耿堂，芸香风度。","客至忘言孰宾主。","一篇雅唱，似与朱弦细语。","恍疑南涧坐、挥谈麈。","霁月光风，竹君梅侣。","中有新亭泪如雨。","力扶王略，志在中原一举。","丈夫心事了、惊千古。"]},{"t":"感皇恩 寿左司吴君章母夫人","f":"曲","c":["晓色静帘栊，婺光千丈。","香满含真泛春酿。","洛花呈瑞，照眼一枝先放。","要将金屑粉、妆仙仗。","月榭焚香，松阴扶杖。","好个人间寿星样。","斓斑舞袖，辉映凤池春浪。","年年称庆日、长无恙。"]},{"t":"感皇恩 寿表弟韩云卿","f":"曲","c":["临事羡君材，笑予拙宦。","待诏云龙更英盼。","梦回孤枕，依旧新丰旅爨。","明时无寸补、空留恋。","绿泛莲波，望高霄汉。","洒洒元康济时彦。","诸公延誉，莫为骥淹台院。","百年安健里、千千算。"]},{"t":"感皇恩 寿董野庄","f":"曲","c":["健羡玉堂仙，中朝元老。","过眼繁华任纷扰。","百年心事，爱煞野庄春好。","南枝谁道是、调羹了。","风月吟怀，冰霜节操。","千尺青松尽难槁。","春宫调护，好个当年皓。","日边消息近、中书考。"]},{"t":"感皇恩 登楼即事","f":"曲","c":["斜日倚高楼，乱峰围绕。","山色湖光翠如埽。","天涯倦客，目断野烟高鸟。","□□□□□、□□□。","老境骎骎，忧心悄悄。","也待凝顽事须了。","故园三径，已是菊荒松老。","诸君应有语、归来好。"]},{"t":"感皇恩 赠提刑曹仲明","f":"曲","c":["把酒爱髯卿，故家风度。","不为临江老能赋。","饱谙世事，成败见来无数。","□□□□□、□□□。","岁月如流，睽离良苦。","更着佳人怨迟暮。","羁愁顿解，一笑团圆儿女。","殷勤君记取、周郎语。"]},{"t":"摸鱼儿","f":"曲","c":["望都门、满山晴雪，匆匆君又西去。","当时汉将征西幕，气压瘴江烟雨。","还自许。","尽虎穴雄深，万里班超举。","燕台再过。","甚牢落高情，霜风偃薄，似厌貂裘土。","弦歌事、正尔邯郸故步。","功名从此轩翥。","一麾回首甘陵树，千室正歌来暮。","须记取。","拊麾外催科，未碍阳城古。","征鞍莫驻。","趁渭北春天，升堂拜慰，捧檄为亲舞。"]},{"t":"摸鱼儿 赋白莲至元二十二年乙酉九月重九后三日雨中作","f":"曲","c":["淡亭亭、影摇溪水，芳心知为谁吐。","玉华宝供年年事，消得一天风露。","私自语。","君不见仙家，玉井无今古。","淡妆谁妒。","尽千顷昆明，红幢翠盖，云锦烂秋浦。","琼绡袜、自有凌波故步。","赏心莫遣迟暮。","风清月冷无人见，零乱碧烟修渚。","闻好去。","待醉浥秋香，不羡风标鹭。","远游重赋。","拟太一真仙，共浮沧海，一叶任掀举。"]},{"t":"满江红","f":"曲","c":["冠剑梁园，又去作、庞眉书客。","休自叹、功名几许，一家风雪。","春色似嫌莺燕老，秋霜历试松筠节。","爱赵生、游刃簿书闲，昆刀铁。","都会地，繁华歇。","形胜在，犹堪说。","更诸君表里，玉辉冰洁。","水陆若论都漕计，夷门忍使黄流坼。","好相须、着力障狂澜，休伤别。"]},{"t":"满江红","f":"曲","c":["秣马膏车，又去作、天涯羁客。","明见得、水云深处，万花如雪。","绿暗江城多洞府，红烧烛影翻双节。","被晓风、吹散枕中春，檐间铁。","尘世事，无穷歇。","吾最爱，沧浪说。","恐灵均泽畔，只成孤洁。","心事比量无少恶，前途何必论龟坼。","倘祥金、陶铸遇良工，从区别。"]},{"t":"满江红","f":"曲","c":["一柱华峰，绿翠似、芙蓉金削。","孤负却、画船春水，一尊同酌。","寒食清明都几日，征鞍遽作西归客。","漫春风、墙燕语留人，高城隔。","春草碧，杨花白。","妆点就，行轩色。","道不应霜翮，能舒长策。","三尺青萍风义在，看君冠盖长安陌。","对夕阳、淡处最关情，河梁别。"]},{"t":"满江红","f":"曲","c":["风月溪堂，也曾是、东州行客。","长记得、相逢一笑，羁愁都雪。","又对青山谈世事，老怀未减元龙节。","恨霜蹄、蹴踏短辕间，论监铁。","官里事，何曾歇。","公等志，吾能说。","尽纵横鞭算，玉壶冰洁。","烂醉春风能几度，桃花未了杨花坼。","甚一城、相望半年过，长如别。"]},{"t":"满江红","f":"曲","c":["雷动云横，惊飙鹜、北城西下。","人共骇、赤丸夜语，电光飞射。","将领未承诸葛令，櫜鞬已在汾阳胯。","笑书生、思握玉鳞符，从公驾。","铃索静，云麾亚。","追往事，何多暇。","道一篇乐府，翰林情话。","日月低回黄阁梦，风云惨淡凌烟画。","尽花边、高冢卧麒麟，终潇洒。"]},{"t":"满江红 为大丞相史公寿","f":"曲","c":["柱石中朝，还不减、汾阳劝考。","人尽道、今年相府，南衙春早。","肘后不知金印大，书中渐觉群众疑少。","问南枝、消息几多春，调羹了。","宝窦暖，香云袅。","晴云霁，西山晓。","见一星朝出，五云萦绕。","汉日舒长铃阁静，雅歌声入江淮渺愿神尖、长对寿眉青，应难老。"]},{"t":"满江红 寿康平章用臣","f":"曲","c":["柱石中朝，人道是、汉家真相。","试看取、凤池高步，佩声清响。","世祖功臣三十六，第动合在云台上。","欲暂分、霖雨霈秦川，从时望。","睿思远，谁能□。","空健倒，骊驹唱。","抚一方何似，际天寅亮。","肘后不知金印重，玉堂正要吾军张。","向五云、深处望三台，光千丈。"]},{"t":"满江红 复用前韵有怀西溪梁园之游","f":"曲","c":["书剑梁园，忆曾是、青骢游客。","宫苑废、三山依约，绿云红雪。","好在西溪王老子，留连醉尽花时节。","记尊前、金缕唱新声，忘筝铁。","襟韵合，曾衰歇。","消客气，歆情说。","尽暮年心事，风霜孤洁。","一片黄流翻晚照，回惊吴楚东南坼。","偶追思、往事叹余生，长年别。"]},{"t":"蓦山溪","f":"曲","c":["冰姿绰约，翠袖翻青露。","林下谢夫人，依然是、故家风度。","搔头玉重，云髻不胜寒，绣帘疏，凉月细，一点香来处。","清标一插，脉脉秋如许。","无语对西风，恍当年、六朝琼树。","幽窗深锁，莫厌惜娉娉，瑶台路，藐姑仙，恐跨青鸾去。"]},{"t":"虞美人","f":"曲","c":["红颜绿鬓无长好。","日对菱花老。","头童齿豁竟何裨。","只有饥时餐饭饱时嬉。","因行消散昏和闷。","却觉筋骸困。","那钱置个马儿骑。","食饮难消，终日系门陲。"]},{"t":"虞美人 谢成耀卿佥事携酒芋相过","f":"曲","c":["山瓶乳酒甘如蜜。","鸱芋堆盘赤。","见君相赠固多情。","润我枯肠一吸破愁城。","秋光湖碧西湾潋。","不到中心慊。","何时尽煮土芝香。","醉饱归来，肯把故山忘。"]},{"t":"鹊桥仙","f":"曲","c":["五穷作祟。","百端相滞。","破帽一风吹碎。","邯郸道上断人行，消铄尽、元龙豪气。","商颜绮季。","当时不起。","误甚汉家经济。","书生薄相到还元，要结末、黄齐滋味。"]},{"t":"鹊桥仙","f":"曲","c":["金莲蜜炬。","紫山仙侣。","梦寐青门瓜圃。","春风着处是行窝，要一笑、人间今古。","锦笺佳句。","新声金缕。","洒遍蔷薇清露。","东华待漏满靴霜，恐输与、西城杖履。"]},{"t":"鹊桥仙","f":"曲","c":["调羹粉桂。","爱香种蕙。","自笑秋风野卉。","两椽茅屋对青山，初不羡、入云高弟。","将心自逸。","欲行且憩。","如爱清时有味。","桐江波上一丝风，尽容得、严光不起。"]},{"t":"鹊桥仙","f":"曲","c":["沉酣往古。","栖迟衡宇。","剧有弓招此举。","长林丰草野麋心，是中散、生平自许。","日边草赋。","矛头炊黍。","谁道闲云有雨。","周宣补衮要深功，除唤起、当年山甫。"]},{"t":"鹊桥仙","f":"曲","c":["金銮视草。","蒲轮应召。","客路人情殊好。","岂知野鹿饰金镳。","志却在、长年丰草。","霜风料峭。","形容枯槁。","愁绪百端萦绕。","故山归去有茅庐，任束置、长沙谏稿。"]},{"t":"鹊桥仙 大德辛丑岁八月初四日寿平章相公夫人","f":"曲","c":["金波秋静，桂兰香重。","瑞应熊罴佳梦。","锦绷擎出玉麟儿，道释氏、老君亲送。","寿筵增庆，朝鞍归控。","恰及瑶觞拜捧。","平津起舞棣华歌，好一醉、玻璃春瓮。"]},{"t":"鹊桥仙 为何继光寿","f":"曲","c":["调和谋断，论思机务。","许大茫茫疆宇。","当年姚宋救时才，听沙路、归来好语。","阶翻红药，省连温树。","满贮春风瑞露。","眼中庭桧郁苍苍，道晚节、昌于韩圃。"]},{"t":"鹊桥仙 寿胡紫山","f":"曲","c":["秋香悬桂。","光风转蕙。","掩尽寻常花卉。","西城来往已风流，更点检、生涯次第。","堂名休逸。","策扶流憩。","占尽闲中风味。","鸡声才动已扶头，红日上、花梢未起。"]},{"t":"鹊桥仙 和刘梦吉韵","f":"曲","c":["高人非古。","冲襟粹宇。","要览德辉飞举。","伊周元不是庸人，吾志在、箕山巢许。","兰纫有赋。","菊香酿黍。","梦断糟床秋雨。","渊明卧老北窗风，犹胜似、清谈夷甫。"]},{"t":"酹江月","f":"曲","c":["遗台树老，独画阑、春事犹未消歇。","好在来禽花盛发，满意清明时节。","翠袖翻香，朱颜晕酒，绰约冰肌洁。","几年空谷，等闲飘坠香雪。","回首绮阁东风，使君情重，一顾倾城色。","只恐花飞春减却，束约尊前欢伯。","起舞山香，醉歌金缕，细按红牙拍。","青鸾高兴，恍然归梦瑶阙。"]},{"t":"酹江月 为友人寿中丞子初","f":"曲","c":["栖迟林壑，甚雍容、雅量气横寥廓。","人道魁然真宰辅，心在朝家黄阁。","几卷闲书，一门清乐，不羡千金橐。","诸郎楚楚，凤毛辉映麟阁。","今岁锦席云凉，菊香添麝，竹树烟霏薄。","风爱堂前秋气好，歌里甘棠如昨。","十二金钗，百壶清酒，细把红螺酌。","年年此日，醉看清献龟鹤。"]},{"t":"酹江月 东原寒食","f":"曲","c":["天涯寒食，问东风、底事留连行客。","千树芳菲春不管，吹尽枝头红雪。","湖水春波，佳人锦瑟，肠断非离索。","西来一剑，不堪尘满霜锷。","凭仗谁话春愁，一尊浊酒，醉了还重酌。","尽日西归归未得，怨煞山中猿鹤。","六印双旌，两都无分，此去从吾乐。","太行佳处，布衣高卧云壑。"]},{"t":"酹江月 赋玉鸂鶒薰炉赠数学刘文卿","f":"曲","c":["客窗凉夕，问故家、何物能慰岑寂。","都把龙涎三万斛，满贮宫池鸂鶒。","玉立琼洲，雪翻花臆，梦绕春江碧。","看云失水，淋漓元气犹湿。","我昨拄杖敲门，主人情重，预报春消息。","相对掀髯谈笑间，一缕飞云摇曳。","暖透天心，冷穿月窟，好个行窝客。","金盘泻露，约君同醉秋月。"]},{"t":"酹江月 赋鸡头","f":"曲","c":["紫荷盘若，向波心、溅溅鸿头高啄。","满喙明珠三百颗，一夕秋风吹落。","沙盎圆搓，麝汤旋煮，香喷佳人嚼。","杯盘凉夜，楚江风味依约。","今岁冷淡中秋，空阶雨湿，坐久寒生幕。","草草时新聊应候，儿子灯前欢噱。","趁暖争拈，分朋斗啮，翠屑纷如削。","老夫旁看，苦吟思与韩较。"]},{"t":"酹江月 福建官舍言怀","f":"曲","c":["散材无用，空拥肿、岂是入时花样。","白发苍颜官舍底，日把早衙来放。","主治官书，隐忧民瘼，拟惬澄清望。","简华霜在，顾予关甚得丧。","□□□□□□，藕丝能系，况忝为司长。","后拥前呵非不欲，梦寐山林长往。","不忆莼鲈，不怀松桂，祗为身多恙。","诸公垂顾，免教憔翠烟瘴。"]},{"t":"蝶恋花","f":"曲","c":["淇水当年麟凤渚。","回首飞翔，落落风云举。","三叠阳关回首处。","渭城柳色朝来雨。","今夕何年天所与。","白发归来，一笑同歌舞。","醉里相将寻杖履。","苕溪风月无今古。"]},{"t":"蝶恋花","f":"曲","c":["绿暗兰皋春雨暮。","露浥风吹，馥馥香如雾。","一曲清歌花解语。","落红羞满沙头路。","锦瑟华年谁与度。","夜月珠帘，肠断春风句。","我自兴来聊一顾。","醉魂不到凌波步。"]},{"t":"蝶恋花 和曲山韵因为赠之","f":"曲","c":["经世此心谁尽了。","欲画麒麟，功业何由到。","白发满头青镜晓。","花开花落人空老。","适意杯盘从草草。","甘坐清贫，方驾郊和岛。","最爱新诗情致好。","篇篇直压元郎倒。"]},{"t":"蝶恋花 赋来禽歇枝","f":"曲","c":["今岁寻芳春已误。","一粒丹砂，不到来禽树。","满意红芳春也妒。","长条簇满珍禽羽。","花道无情应有素。","似惜金尊，一醉珠帘暮。","春自还来花自故。","人生最恨离筵苦。"]},{"t":"鹧鸪天","f":"曲","c":["拾翠仙洲野兴长。","尊前一曲杜韦娘。","人怜暖日明歌扇，我爱兰英媚国香。","供楚佩，笑梅妆。","春风着意泛崇光。","老怀不到凌波梦，要遣琵琶送一觞。"]},{"t":"鹧鸪天","f":"曲","c":["波荡江湖万里余。","归来缩首伴凡鱼。","门从席后轩车盛，鬓自霜来宦味疏。","思往事，注残书。","闲锄明月种秋蔬。","傍人莫笑扬雄宅，好事时过载酒壶。"]},{"t":"鹧鸪天","f":"曲","c":["门外东风驻马蹄。","月明庭树绿阴稀。","眼中时事惊天运，醉里游谈似□机。","思远走，拟高飞。","此心安得与时违。","遗书浩荡三千卷，未分穷愁老布衣。"]},{"t":"鹧鸪天","f":"曲","c":["野粉宫墙暮两边。","洛京依旧锁婵娟。","一声金缕关情处，满串骊珠讶许圆。","金谷月，石楼烟。","留连光景待他年。","袜尘休放凌波去，更听新翻倒玉船。"]},{"t":"鹧鸪天","f":"曲","c":["先相风流德业尊。","又看天马五花文。","飘飘青琐凝佳思，霭霭新诗似岭云。","淮海秀，已平分。","圭璋未碍琢来勤。","吴人元重中州气，绣被何尝擅鄂君。"]},{"t":"鹧鸪天","f":"曲","c":["潦倒衰翁不足尊。","更堪刺口论诗文。","经途江浙多兰友，照眼吴山霁雾云。","伤别久，惜轻分。","临歧一语见微勤。","万艘未是周郎志，他日经纶要使君。"]},{"t":"鹧鸪天","f":"曲","c":["何处人间淑景新。","韶光都付牡丹春。","后庭花老空琼树，曲水江深见丽人。","金屑粉，麝香裙。","近前细看倒芳尊。","惜教赤壁矶头月，吹散春风陌上尘。"]},{"t":"鹧鸪天","f":"曲","c":["闾井锥刀剧战烘。","咏归奚取舞雩风。","道开圣学千年后，春在先生一亩宫。","敦诲诱，见从容。","弦歌不隔幔纱红。","珉溪几点梅梢雪，岁岁吹香入寿钟。"]},{"t":"鹧鸪天","f":"曲","c":["浴凤池边养相材。","朝端先肃汉仪开。","九秋灏爽临初度，千丈恩光动宪台。","锵剑佩，望蓬莱。","翠华南扈拂天来。","一枝好在霜前菊，留待清香荐寿杯。"]},{"t":"鹧鸪天","f":"曲","c":["花草离骚试品量。","猗猗香色紫兰芳。","乐棚擢秀名何丽，楚泽含秋思更长。","金缕曲，紫霞觞。","留连光景醉银塘。","竹西歌吹归时晚，也胜扬鞭问葛疆。"]},{"t":"鹧鸪天 为王太夫人寿","f":"曲","c":["簪纚潇然自谢林。","一家柔范到周南。","以贤论母书彤管，有子能官尽孝心。","香雾碧，寿尊深。","岁时春辇醉花阴。","从今业庆堂前月，翠竹高梧听凤吟。"]},{"t":"鹧鸪天 为乐籍张惠英赋","f":"曲","c":["秋水芙蓉镜里仙。","一枝明玉濯烟鬟。","莺初解语调柔石，柳不胜娇拂画阑。","催叠鼓，按弓弯。","楼心低月怯清寒。","人生莫惜缠头锦，能得春风几度看。"]},{"t":"鹧鸪天 为耶律总管太夫人寿","f":"曲","c":["辽海千年将相家。","婺星光动赤城霞。","回首画戟清香地，满意春风玉树花。","金椅背，紫云车。","谢林风度见来赊。","寿波潋滟宫壶暖，满泛秋光醉绿华。"]},{"t":"鹧鸪天 寿李靖伯母","f":"曲","c":["香静堂萱燕处温。","一家柔范被乡邻。","三牲奉养真纯孝，八十康宁是福人。","岩菊晚，岭梅春。","丰容林下旧精神。","婺光不动云衢烂，供佛床头景气新。"]},{"t":"鹧鸪天 谒太一宫赠王季祥","f":"曲","c":["来谒齐宫又五年。","道人邀我坐前轩。","只惊前度刘郎老，不见庭松偃盖圆。","人与境，两翛然。","呼童茶罢炷炉烟。","壁间一轴烟萝子，依约风流堕眼前。"]},{"t":"鹧鸪天 赋鲍家黄","f":"曲","c":["何处人间淑景新。","刘家池馆鲍家春。","后庭花唱空琼树，曲水宫妆见丽人。","金作粉，麝为尘。","一枝千叶拥黄云。","花工可是多情思，梦逐凌波问洛神。"]},{"t":"鹧鸪天 韩氏别墅","f":"曲","c":["竹映方台翠满湖。","烟霏荷露净郊居。","棣花辉映春风被，云锦香翻碧玉壶。","吟倚杖，卧看书。","一家风景辋川图。","酒杯尽泛床头瓮，未碍门多长者车。"]},{"t":"鹧鸪天 赠驭说高秀英","f":"曲","c":["短短罗袿淡淡妆。","拂开红袖便当场。","掩翻歌扇珠成串，吹落谈霏玉有香。","由汉魏，到隋唐。","谁教若辈管兴亡。","百年总是逢场戏，拍板门锤未易当。"]},{"t":"小桃红","f":"曲","c":["采菱人语隔秋烟，波静如横练。","入手风光莫流转。","共留连。","画船一笑春风面。","江山信美，终非吾土，何日是归年？"]},{"t":"越调·小桃红","f":"曲","c":["平阳好处是汾西，水秀山挼翠。","谁道微官淡无味？","锦幛泥。","路人争笑山翁醉。","西山残照关卿何事？","险忙杀暮鸦啼。"]},{"t":"后庭花破子","f":"曲","c":["绿树远连洲。","青山压树头。","落日高城望，烟霏翠满楼。","木兰舟。","彼汾一曲，春风佳可游。"]},{"t":"平湖乐","f":"曲","c":["安仁双鬓已惊秋。","更甚眉头皱。","一笑相逢且开口。","玉为舟。","新词淡似鹅黄酒。","醉扶归路，竹西歌吹，人道是扬州。"]},{"t":"拜奠宣圣林墓","f":"楚辞体","c":["庭训堕渺茫，师授悖严诫。","羌予不惑年，行己得夷隘。","今岁客东鲁，似为神所介。","驾言逐秋风，得展阙里拜。","遥遥鲁甸馀，汶水走湍濑。","凭轼望云林，郁郁佳气叆。","齐庄趋两楹，奠献成孤酹。","岿然三圣封，仰止高泰岱。","恨生千年后，今夕备扫洒。","披云睹天日，太极开一画。","彼苍讵能言，谆谆圣为代。","三纲与九法，范围无内外。","君臣以之定，乾坤以之泰。","东周不可为，述作万世赖。","藐聆徇铎音，元化雷雨解。","敬想燕居容，金声锵玉佩。","当时七十子，授受俨如待。","凤兮鸣几时，诸子沸秋籁。","一朱乱红紫，百谷茷稊稗。","愚者甘下达，诞者乐语怪。","韫藏宝康瓠，斡弃清庙鼐。","明伦得不泯，而有六经在。","天高孰可阶，一气包厚载。","兹游固难言，默契心有会。","胸中九云梦，吞纳失蒂芥。","循循善诱辞，师也书诸带。","缅怀伯禽业，郁郁文献最。","三桓张公室，霸功炽而忲。","一奢去无复，荒陵馀石獬。","煌煌天乙孙，肤敏半冠盖。","德博庆自修，道大世能迈。","金石贯元精，泗波来远派。","汪濊一圣海，不随梁木坏。","归侍金丝堂，摄齐闻謦欬。","恍如到帝所，钧天广乐备。","洗我两耳聪，肉味忘一嘬。","咏归写遗音，风雅变鄘邶。","一箪老东家，吾知其乐大。","迟迟不忍去，寒日下苍桧。"]},{"t":"陪总管陈公肇祀商少师比干庙","f":"五言古诗","c":["元化形万汇，浩浩无时无。","云何忠贞气，大畀先生躯。","念昔有殷季，天步移独夫。","淫酗荡祀典，下民为毒痡。","所崇尽奸回，启遁箕子奴。","师保乃去尔，馀敢编其须。","炎炎鹿台火，已兆明珠儒。","先生岂不知，蔓草不可图。","顾亲叔父尊，以位仍三孤。","强谏诚我任，剖心不为愈。","自靖暨杀身，要之宗社扶。","所以宣父笔，三仁同一途。","繄公存亡间，所系重有殊。","堂堂柱天手，能摰火德乌。","当时戡黎兵，所侵良及肤。","周虽彼苍眷，加翼十乱谟。","天其谏少行，终鄙西人居。","称师止观政，安取商郊车。","一朝叹云亡，宗国随之墟！","丹诚皎白日，馀烈光八区。","准尔来代臣，大节知所趋。","呜呼介士叹，万万狂童且。","今来二千载，殷周两榛芜。","巍然一丘土，高与西山俱。","清霜九月节，肇祀陪干旟。","肃拜列阶下，精爽动佩裾。","世道有沦丧，一忠千万谀。","商歌振林樾，日下悲风徂。"]},{"t":"鹿喻","f":"五言古诗","c":["我本麋鹿性，出处安自然。","金镳非所慕，志在长林烟。","得远机阱地，食苹饮清泉。","呦鸣锡同类，甘以辞华轩。","野兕出其侧，暗蹂山前田。","农家伺所害，乃知兽之愆。","彼兕以计去，嘉禾岁芊芊。","野人居山中，数亩事垦斸。","虑为町疃场，指鹿乃兕属。","虽无擉刃心，见之恶且逐。","鹿心素无机，淡与标枝閒。","遁迹入幽谷，择音远人寰。","尚为山中人，置疑齿颊间。"]},{"t":"过刘元海陵寝","f":"五言古诗","c":["汉统天久绝，汉恩一何深。","隔远魏晋代，犹足收民心。","咄嗟呼韩子，崛起蒲离阴。","自云汉婿甥，赫怒开实沈。","左顾龙在野，右咤虎啸林。","吹嘘炎烬馀，五部来讴吟。","阿聪奋馀烈，两京随扫平。","窃据二纪强，文物有足矜。","我来拜陵寝，悚然振冠缨。","风云渺何许？","废堞馀金城。","贤哉刘淑妃，成此直谏名。","在聪未为疵，假义渊可称。","孰云仁义师，可敌不可征。","桓桓祁山举，一出三辅惊。","天其假公年，载洗六合清。","此志竟莫遂，此邦还有成。","所以广武叹，痛惜无豪英。","山烟知客意，斜日生荒陵。"]},{"t":"游万固寺","f":"五言古诗","c":["中条郁苍苍，首尾固雄大。","连山一卧虎，矫首尽两戒。","东南万峪门，荦确入幽阨。","空青上绝壁，巀嶪两崖对。","南山开画屏，高下蔚万桧。","扶藜到山门，黄衣六七辈。","寺残薄水赏，一水良可爱。","寻源入云萝，不惜阮屐败。","掬饮清臆尘，坐睨巨石怪。","山空响佩环，林迥腾怒獬。","行听溪声回，周览询胜概。","当年爽心亭，万竹争映带。","碧鲜照清泚，襟袂濯沆瀣。","人境两渺茫，佳句尽誇迈。","开轩邀客饭，放目欣一快。","盘餐固疏粝，泉洌几肉嘬。","少焉林风振，万壑一气噫。","前林疑虎啸，作勇助吾惫。","笔落还自惊，一扫众峰叆。","山僧喜醉颠，海会得珠贝。","兴来本无心，游藏诧佛界。","夕阳送归鞍，依约虎溪外。","风烟作破墨，塔庙失所在。","钟美厌摹写，閟伏化机蔼。","盘空乏硬语，技痒若无赖。","马首诗遽成，一笑豁吾隘。"]},{"t":"沁水道中","f":"五言古诗","c":["苍巅互出缩，峪势曲走蛇。","回眺惊后拥，迎看复横遮。","云林荡高秋，半岭翻晴霞。","十里九渡水，清流带寒沙。","山溪本幽寂，激之声乃哗。","解鞍憩美荫，觉我心静嘉。","风枝满秋实，野菊被水涯。","幽馨散兰馥，红鲜缀丹砂。","二物固琐碎，托兴骚人誇。","我欣记所见，信笔书田家。"]},{"t":"过鹿台山","f":"五言古诗","c":["远寻文石岗，来历南山缠。","鹿台台为山，幽径蟠古篆。","后峪行未尽，前岭已当面。","秋声荡林樾，风露凄以泫。","阴壑气蓊郁，疑有虎豹变。","山田苦无多，沟崦耕已遍。","柴楥结半空，罗络碧岩转。","自怜终岁勤，兽患防一旦。","我本山中人，束带对邮掾。","顿然还旧观，潇洒偿夙愿。","行经双蟾岭，石怪惊变现。","闯首槲树间，气自太古练。","月中谁推坠，囚锁属山县。","乃知北平守，认虎饮羽箭。","物肖本偶然，长歌下层巘。"]},{"t":"御骠出厩图","f":"五言古诗","c":["何人拂绢素，写此房驷精。","一马老伏枥，志在千里行。","二马骋踶齧，角壮犹龙腾。","一马方辊尘，海岸翻鲲鲸。","画师惨淡意，落笔矜多能。","我观寓所感，国制贵有经。","唐人重马政，分屯列郊坰。","当时百万匹，肃肃罗天兵。","东封与西荡，岁用不可胜。","嗣王猎其馀，尚足开中兴。","乃知三军本，匪马将奚凭。","圣经说备预，万古为世程。","仓卒事亦办，未免众目惊。","我思立仗间，振鬣伸长鸣。","吾言固刍荛，圣经其可轻。"]},{"t":"苦热叹四十六韵","f":"五言古诗","c":["祝融驾火虬，顿辔周八裔。","战酣西北乾，回薄馀暮炽。","朱光沸虞渊，大地蒸一气。","苍茫夜色湿，酗郁玄象醉。","今年六月中，荼毒逾往岁。","金晶才始伏，熛怒势此锐。","炎官张火伞，屏翳扬赤帜。","四合歊陈来，一鼓赫离治。","天潢影半涸，星鸟芒欲彗。","吟风树叶噤，塌翮林鸟坠。","并兼坎兑权，不使天地闭。","王城十万家，薰灼迫一势。","乾坤堕炽瓮，逸德骇天吏。","掩关人事绝，藏伏敢口议。","褰裳起中夜，通夕不容寐。","扪背赭汗流，窥井汤泉沸。","松间有困鹤，无梦到清唳。","墙根有腐草，萤化光晢晢。","穿帘入我室，照眼惊火齐。","阴蟾遁老魄，火鼠骋黠智。","夜深过我前，跳踯翻饮器。","屋古又足蝎，伺螫尤谨避。","簟纹燎炎辉，侧胁能少憩。","举动体愞熟，歔欷气短细。","抱水眠或可，挥翣何所济。","二年客京师，身幸置散地。","虽无束带劳，唯老觉加倍。","彷徨不知曙，种发沐而被。","四序本平分，偏盛谁所致。","火攻出下策，不已熸万类。","嗟此一世人，暍死将何厉。","此生匪金石，流铄吁可畏。","内热复自焚，衰槁将立至。","燥惟以静胜，事须以义制。","冰山讵可依，炀灶非所媚。","遐想昆陵巅，庭观何伟丽。","巍然五千仞，日月光隐蔽。","回环十二楼，空明淡无际。","水晶作柱础，群玉绚轩陛。","天风掠枕席，月露湿环帔。","瑶台拥灏灵，万舞发清吹。","真仙事朝元，鸾凤互骖翳。","阆风接玄圃，追陪忆游戏。","何年堕尘缘，坐想无由诣。","安得万里风，振此垂天翅。","脱落区中囚，高举寻吾契。"]},{"t":"野河渡","f":"五言古诗","c":["苍茫刘桥渡，南北凡几过。","清霜十月交，澄湛东流波。","饮马立水边，照我两鬓皤。","行役非所苦，伤怀动悲歌。","三年恒山赵，弹劾兼拊摩。","嗷嗷眼中民，力弊差与科。","不能一勺润，慰彼烦与痾。","顾此衣带水，溉载功实多。","人而反不若，低首愧野河。","素餐吾可逃，奈此苍生何。"]},{"t":"挽漕篇","f":"五言古诗","c":["汤汤汶水波，西骛复东注。","势虽汗漫来，止可流束楚。","发源本清浅，才夏即沮洳。","安能浮重载，通漕越齐鲁。","有时汎商舶，潦涨藉秋雨。","船官行有程，至此日艰阻。","钜野到齐东，著浅凡几处。","必资州县力，涩滞方可度。","漫村赶丁夫，所在沸官府。","先须刮流沙，推挽代篙橹。","硬拖泥水行，奚异奡荡努。","涉寒痹股腓，负重伤背膂。","咫尺远千里，跬步百举武。","兹焉幸得过，断流行复阻。","又须集牛车，陆递入前浦。","中间吏因缘，为弊不可数。","蛮梢贪如狼，总压暴于虎。","所经辄绎骚，不若被掠虏。","盻盻入海口，未免风浪鼓。","舟中一斛粟，百姓几辛苦。","今复起堰坝，壅积百方禦。","木石动万计，科配困氓伍。","不思根源微，堤障深几许。","转漕本便民，广储实国补。","事功贵顺成，勉强终龃龉。","海道事已然，又复有此举。","惜将生民力，委弃若泥土。","山东实重地，一静乃可抚。","尝闻建隆间，有相曰赵普。","凡百投利人，罢遣皆不取。","以兹报国恩，后世比申甫。","黄阁十馀年，清风一万古。"]},{"t":"过深州故城有怀韩昌黎解牛元翼围事","f":"五言古诗","c":["维唐有藩镇，连衡皆盗区。","污孽互相济，殆似背胁疽。","心腹讧蟊贼，膏血化虫蛆。","厉阶安史乱，王泽不远敷。","河朔有故事，誓作效逆徒。","堂堂裴中令，夷蔡恢皇图。","聊乘破竹势，一制三镇污。","腐败就与决，大赫天王诛。","彼相中妒梗，百裴竟无如。","事机一堕地，涵溃终丧躯。","所以贼凑辈，血人于牙须。","既戕弘正忠，复抗新使符。","靖安门昼锁，长围困貔貙。","昌黎解一言，王略始得舒。","信乎立大事，临机见真儒。","东征过故城，往事秋风徂。","得人国无弱，怀古重欷歔。","文公岂多得，元翼何代无。"]},{"t":"出香奇石","f":"五言古诗","c":["张生贮奇石，携来有遐观。","一峰华不注，堕我几案间。","穿穴作怪供，突兀横苍颜。","炷香烟满窦，野烧生春山。","我久汩俗冗，对之心暂间。","瞑坐清兴远，梦与孤云还。"]},{"t":"汲冢怀古","f":"五言古诗","c":["迩迤伍城郡，背水犹陈图。","魏陵废已久，磅礴如覆盂。","草树惨不春，穿穴狐狸墟。","我来登其颠，怀古心踌躇。","忆当战国际，安釐亦狂且。","泽麋被皋比，坐为秦人驱。","败亡自此始，保邦何乃疏。","不知身后藏，安用书十车。","上窥姒与商，下逮苍周书。","零乱竹简光，诡说何纷拿。","征南辨已详，多出行怪徒。","稽古不适正，死为毛颖诬。","其中亟当辨，阿衡被夷诛。","孔子修六经，亦已防奸污。","大书一德后，薨葬开亳都。","在易最奇法，安取理所无。","兹焉万世程，洋洋真圣谟。","何烦事幽赜，致远泥所趋。","长歌望陵去，乐过风乎雩。"]},{"t":"双庙怀古","f":"五言古诗","c":["铁舆动地来，猎火烬九县。","睢阳东南冲，江淮国所援。","蔽遮不使前，恢复可立见。","二公明此机，死守誓不变。","虽危所保大，如蝮螫解腕。","最难结众心，存殁匪石转。","彼苍畀全节，谁为落贼便。","已矣君不忘，握爪掌为穿。","竟能济中兴，淮海了清奠。","至今忠烈气，皎皎白日贯。","贺兰观成败，不饮浮屠箭。","杀亡计多寡，此论诚可辨。","我来拜遗像，凛对如生面。","乞灵激懦衷，剸决刚同鍊。","朔风吹树声，尚想登陴战。","暮倚晕月城，悲歌泪如霰。"]},{"t":"江船二咏 其一 篷","f":"五言古诗","c":["尺箦编黄芦，节□数须只。","长短随所宜，张弛易为摘。","一傍系脚索，若网纲总缉。","北人布为帆，南俗篷以荻。","舟师贪重载，高挂借风力。","顺流与溯波，巨鹢添羽翮。","望从远浦来，一片云影黑。","乱冲渚烟开，重带江雨湿。","百里不终朝，用舍从顺适。","夕阳见晚泊，堆叠纷襞积。","水虽物善利，其助乃尔益。"]},{"t":"江船二咏 其二 橹","f":"五言古诗","c":["江船一钜鱼，橹柁乃尾鬣。","当其渊水深，棹弱不救乏。","故令施航后，前与棹力合。","济川具有五，此物乃其甲。","一声天际来，欸乃中流发。","或浮大河东，并岸行若狎。","终朝卧舷间，兰桨但空插。","缅怀剡木皇，智创万古法。"]},{"t":"食鲈鱼","f":"五言古诗","c":["鲈鱼昔人贵，我行次吴江。","秋风时已过，满意莼鲈香。","初非为口腹，物异可阙尝。","口哆颊重出，鳞纤雪争光。","背华点玳斑，或圆或斜方。","一脊无乱骨，食免刺鲠防。","肉腻胜海蓟，味佳掩河鲂。","灯前不放箸，愈啖味愈长。","张翰为尔逝，我今赴官忙。","出处要义在，不须论行藏。","倚装足朝睡，且快所欲偿。","梦惊听吴歌，海日方苍凉。"]},{"t":"东征诗","f":"五言古诗","c":["东藩擅良隅，地旷物满盈。","漫川计畜兽，荡海驱群䲔。","盛极理必衰，彼狡何所惩。","养虺得返噬，其能遁天刑。","远接强弩末，近訹乳臭婴。","一朝投袂起，毡裘拥矛矜。","天意盖有在，聚而剿其萌。","荓蜂有螫毒，大驾须徂征。","寅年夏五月，海甸观其兵。","凭轼望两际，其势非不勍。","横空云作阵，裹抱如长城。","嚣纷任使前，万矢飞欃枪。","我师静而俟，衔枚听鼙声。","夜半机石发，万火随雷轰。","少须短兵接，天地为震惊。","前徒即倒戈，溃败如山崩。","臣牢最忾敌，奋击不留行。","卯乌嗢都间，天日为昼冥。","僵尸四十里，流血原野腥。","长驱抵牙帐，巢穴已自倾。","彼狡不自缚，鼠窜逃馀生。","太傅方穷追，适与叛卒迎。","选锋不信宿，逆颈縻长缨。","死弃木脔河，其妻同一泓。","彼狡何所惜，重念先王贞。","择彼顺祝者，其归顺吾氓。","万落胁罔治，无畏来尔宁。","王师固无敌，况复多算并。","君王自神武，岂惟庙社灵。","三年哂东山，殪戎营柳清。","都人望翠华，洗兵雨何零。","长歌入汉关，喜气郁两京。","小臣太史属，颂德职所承。","虽非平淮雅，动荡耳目精。","赫赫桓拨烈，仰之如日星。","泚笔为纪述，发越吾皇英。","召穆美常武，且莫誇雷霆。"]},{"t":"觅风字歙砚诗赠侍其府尹","f":"五言古诗","c":["砚本发墨具，不尔安用他。","碧紫晕鸲眼，黝黑深宫鸦。","彼端类高人，风姿固云佳。","远韵不少吝，清谈浩无涯。","但于当机时，未免思棼拿。","若或砥砺用，茫然手空叉。","硬则墨为褪，软则磨泥沙。","惟歙士之杰，体性何交加。","罗纹与刷丝，一寸皆可嘉。","回视端溪公，有名实则差。","新安山水窟，泽大生龙蛇。","举世被其利，何有蛭与蛙。","山高溪水清，其芒例如碬。","尝闻右军砚，风字琢手奢。","是名为水箕，朵颐骇唅呀。","松煤烬无馀，惟恐中书丫。","池宽水瀰漫，挹彼如尊洼。","陂陀浸半海，挥洒生云霞。","平生未尝有，梦寐江之涯。","君今去为邦，过此空成嗟。","包公尹端州，归不一砚拿。","彘肝类安邑，一笑春生华。","书生乞索态，殆是心贪邪。","祢衡溺所爱，竟糁渔阳挝。","今冬与来春，会有泛斗槎。","雄雯或雌缦，分送张华家。"]},{"t":"游妫川水谷太玄道宫","f":"五言古诗","c":["迎谒次妫野，将为旦夕间。","尚馀百里远，却得三日闲。","追陪玉堂翁，清游指仙山。","穷秋草木尽，诸峰惨无颜。","两崖蓄馀暖，岩树如春妍。","洞口疑有光，望中已欣然。","始至觉夷旷，稍深更幽宽。","山英喜客来，夜雨濯翠鬟。","层峦与叠巘，供我拄笏看。","云封石上钵，玉漱山腰泉。","灌溉滋树艺，一脉穷湾环。","西台颇峻绝，两折跻其巅。","诗翁见精健，登顿不作难。","䃲礴凛莫留，松风吹袂寒。","降阿集晴疏，高谈渺孤攀。","山荒苦无称，似待新诗传。","诸君垂橐来，稛载风烟还。","因公得胜赏，此诗其可缓。","但恐云霞举，暮景去犹悭。","我非桓野王，今识东山安。"]},{"t":"飞豹行","f":"七言古诗","c":["二年幽陵阅丘甲，诏遣谋臣连夜发。","春蒐秋狝是寻常，况复军容从猎法。","一声画鼓肃霜威，千骑平岗捲晴雪。","长围渐合汤山东，两翼闪闪牙旗红。","飞鹰走犬汉人事，以豹取兽何其雄。","马蹄蹴麋歘左兴，赤绦撤镞惊龙腾。","锦云一纵飞尘起，三军耳后秋风生。","豹虽逸才不自惜，雨血风毛摧大敌。","风烟惨淡晚归来，思君更上单于台。","血埋万甲战方锐，爪牙正藉方刚才。","古人以鹿喻天下，得失中间系真假。","元戎兹猎似开先，我作车攻补周雅。","大笑南朝曹景宗，誇猎空惊弦霹雳。","何曾梦见北方强，竟堕闭车甘偃息。","扬鞭回首汉家营，一点枪缨野烟碧。"]},{"t":"大雹行","f":"曲","c":["雷师掠地西山麓，北会丰隆出苍峪。","崩云掩落赤日乌，列缺光腾烛龙目。","黑风驾海天外立，万骑先声振林谷。","云涛怒卷恶雨来，中杂冰丸几千斛。","杀声咆哮屋碎瓦，百万神兵自天下。","奋然横击合阵来，昆阳之战何雄哉！","又如马陵之道万弩发，矢下雨如无魏甲。","斧形鸡卵见自昔，异状奇模此其匹。","野人庭户变绡馆，雾涌烟霾与龙敌。","又疑鲛人泉客泣相别，泪洒珠玑恣狼藉。","叶穿鸟死庭树惨，禾麦击平惊赭赤。","神威收敛俄寂然，潇潇合浦还珠玭。","整冠变色立前庑，但见土窝万杵一一皆深圆。","五行有占非小变，调元失所谁之愆？","又闻夏冬愆伏之所致，亦以坎冶持化元。","孔子修《春秋》，二百四十二载间。","特书雨雹凡两次，大率贬黜臣下侵君权。","况今朱明壮阳月，胡为纵此群慝之所颛？","历关上诉九虎怒，虮虱小臣非所言。","独怜田家被灾者，寒耕热耘手足成胝胼。","差科大命寄一麦，盻盻见熟疗饥涎。","一新到口不得食，哀哉何以卒岁年！"]},{"t":"捕鱼歌","f":"楚辞体","c":["坞西溪水深及篙，渔户晓集拖轻舠。","纵横张网截两涘，挺叉远混惊银鱽。","柳阴潜涔深且密，大鱼小鱼争遁逃。","须臾合网环深碧，薄掺提纲从掇拾。","小鱼骨挂半死生，口颊噞喁无足惜。","就中一鱼匪常材，黄金作鳞尾砂赤。","泳游本在孟津居，波荡江湖事行役。","中涂遇厄梦不神，腾跃舟中有时立。","渔郎回艇催归急，几处金盘待鲜食。","夕阳澹澹洲渚空，回风潇飒溪神泣。","网罟设兮水不深，役物而君戒贪得。","古人数罟不入池，以时渔捕须盈尺。","今人古道弃如泥，竭泽焚丘意方毕。","野人有乐在濠梁，泽畔行吟三叹息。"]},{"t":"宿仙山朝元观题示","f":"七言古诗","c":["太行北走开四门，川原落落风烟屯。","仙山西峙如虎踞，石岭东抱犹龙奔。","道林中蟠百馀亩，顾揖殿寝何雄尊。","仙翁得仙事惝慌，碧霞洞主玄元孙。","百年朝元去不返，宝箓秘泄风雷燉。","阴灵诃护石坛古，老雨留渍苍苔痕。","缅怀矫矫东瀛老，变化能大天溟鲲。","谢公本是济时具，谁使卧老东山墩。","丰碑不愧蔡邕笔，再拜遗像俨以温。","我来夏交树阴翳，万橘翠琐芬兰荪。","平生素有林壑癖，苦厌圜圚埃霾昏。","每来福地爱潇爽，跬步乃与仙凡分。","山川景气得人胜，喜对羽客开清樽。","夜深静卧月东出，林影布地翻瑶琨。","天风吹空万籁息，明星当上手可扪。","恍然人境两奇绝，月露一洗清心魂。","世间尘土几千丈，有梦不到瑶台垠。","人生几何胡不乐，例自局束驹服辕。","惜哉清景不可驻，一声啼鴂开林烟。","明朝人事随日出，坐看蚁穴蜂衙喧。"]},{"t":"僧传古坐龙图严东平所藏至元二年秋九月张签省耀卿处观七年闰十一月甲戌公退马上偶得时秋苦旱冬天无雪","f":"曲","c":["深山大泽物所蛰，千丈县淙挂青壁。","潭阴水黑不见底，老雨初开元气湿。","苍龙何处行雨归，闯首踞坐红云堆。","山僧骇绝噤不语，万壑阴雾生缁衣。","咄哉传古隐龙性，隔户写影窥天机。","一从元化堕此笔，饮海不复观晴霓。","世间画本万尺蠖，尾鬣一掩无晶辉。","比年一旱几焚如，牲币空事山川雩。","群龙痴睡洞府黑，六合任使黄霾污。","何当铁匣出雷火，冲屋而去腾天衢。","六丁奔命仆射御，倒卷溟渤天瓢?。","滂沱一洗乾坤净，却敛神功寂若无。"]},{"t":"赵邈龊虎图行","f":"曲","c":["巅崖老树缠冰雪，石觜枒杈横积铁。","北平山深林樾黑，下虽有径人迹灭。","眈眈老虎底许来，抱石踞坐何雄哉！","目光夹镜尾束胯，百兽却走潜风埃。","赵侯欲尽神妙功，都著威棱阿堵中。","想当䃲礴噀墨时，众史缩手甘凡庸。","至今元气老不死，神物所在缠阴风。","前年驱马下靖边，崖东突起草底眠。","腰间恨无铁丝箭，寝皮食肉空长叹。","今朝过喜一嚼快，熟视须顶为摩编。","货驯蹠服暴戾息，弭耳道义思拳拳。","主人爱玩中有谓，遇事炳变通经权。","我闻汉家大猎阹冰天，豸冠思赋长杨篇。","四方猛士今云合，早晚龙旂到渭畋。"]},{"t":"清江引为僧永真赋","f":"曲","c":["秋江水清深几竿，渔郎放舟烟渚间。","中流举网紫鳞出，不祇博酒供盘飧。","借问渔翁乐何主，泛宅浮家无定所。","卖鱼生怕近城门，肯到红尘污人处。","芦花两岸晚潮平，忆著莼鲈思径去。","朝廷物色那可得，泽畔行吟何自苦。","沧浪水清濯我缨，林婆酒熟容赊取。","人间万事一醉休，睡煞江南烟与雨。","觉来满眼是青山，独速绿蓑还自舞。","渔父乐，真可与，细泻焦桐入新谱。","朅来山城官事纷，簿书凫吏对斜曛。","开图空会渔家趣，我恨不若江头人。"]},{"t":"醉歌行","f":"七言古诗","c":["苍陂水涨玻璃滑，堤柳含烟翠蒲茁。","当年亭馆已陈迹，老树遗台犹秀拔。","我来置酒池上头，使君不负骢马游。","县曹供张散平碧，呼集妓乐罗珍羞。","君侯一笑开怀抱，十日东风醉芳草。","自嗟客子何所有？","春色三分二分老。","人生欢乐不易得，况值清明时节好。","终年尘土簿书里，未碍金尊重倾倒。","湖光照眼明罗绮，碧潋瑶翻歌扇底。","气酣急遣张水嬉，取乐不论冠佩委。","溪风吹面縠纹生，两叶兰舟铙鼓起。","红衣飞坠彩绳高，没入苍烟惊跃鲤。","郡人亦喜岁华新，四面纵观空巷里。","佳人弄水祓不祥，公子联镳特观美。","锦筵香细酒不空，既醉穷欢忘誇靡。","溪神捧出柘枝娘，翠袖娉婷矜便体。","绣靴画鼓随节翻，罗袜尘生步秋水。","一春盛集固云乐，此会宾僚尤燕喜。","山阴修褉晋诸贤，畅叙幽情差可拟。","客言行春似蜀守，醉到浣花而已矣。","树梢晴日向斜晖，使君皂盖先醉归。","就中二公最爱敬，移次临流尽馀兴。","一杯未了风翻浦，山公倒载寻归路。","自怜白发非春事，多为湘妃厌歌舞。","呼儿觅纸纪岁时，不以斯文乌所睹。","至元乙亥三月春，元巳才过日在寅。","浩歌月底还自笑，醉里诗成似有神。"]},{"t":"玉壁城怀古至元甲戌冬十月廿五日由稷山入万泉道出故城临风吊古慨然有作","f":"七言古诗","c":["我行河东几欲遍，大抵盘回山阜转。","南崖高与北山齐，玉壁城根分一线。","荒烟废垒点抔土，炮具梯冲经百战。","短碑盛说郧君灵，万骑阴风想平甸。","一曲悲歌敕勒川，当时神武已凄然。","韦公守禦尽良策，更著百斗飞上天。","乃知诬杀咸阳日，即是邕皇入邺年。"]},{"t":"羽林万骑歌","f":"曲","c":["韦娘鸡晨遵篡武，牝雏啄李求太女。","履霜得冰忽深戒，祸始房陵帝私语。","神龙殿前虹贯日，王气龙池濯烟缕。","羽林万骑骁且雄，守捉内外生阴风。","鞯裁文豹虎衣炳，扼腕久弗诸韦容。","潞州别驾眼横电，虬髯英姿真太宗。","暗中结纳许清禁，继以幽求玄礼仙凫忠。","玄武门前听二鼓，散乱天星陨如雨。","平明一扫妖氛空，相王已是玄真主。","东城瑞霭朝日鲜，五王甲第临天渊。","三郎归来龙在沼，晴波翠滟终南烟。","开元隆平此张本，烟火万里春熙然。","谁图勇断蛾眉剑，翻作环儿并辔鞭。"]},{"t":"日蚀诗","f":"曲","c":["至元十四载，维龙集丁丑。","孟冬丙辰朔，诘旦阴风吼。","朝家有移告，日蚀百司守。","伐鼓币用社，庶啬鬨奔走。","都城十万家，竟日喧釜缶。","壮于田单兵，声势助冲掊。","盎水观日景，占刻入午辰。","阳精从西亏，若有物噬吞。","初看偃珥玦，再睹已半轮。","终风转蓬勃，天影惨以昏。","斯须食之既，阳光蔀无垠。","始似昏晕镜，久乃挂铁钲。","团团溢阴影，环轮玉为绳。","晴天朗昼藏厚夜，九衢草草人面青。","众宿不多出，争光见三星。","只愁六凿浑沌死，苍生百万沦幽冥。","盼盼向申正，轮圆复其明。","炷香再拜立前庑，心魄动荡久尚惊。","邻翁行年八十一，如此灾变见未曾。","我问长老说，日月中有乌兔精。","顾兔固微物，性狡阴邪萌。","人间三窟厌不处，缘云入月为家庭。","太阳养火乌，赫赫森神兵。","词内祝融家，渴饮咸池泠。","三足利钩戟，炬火燃两睛。","婪婪铁作喙，啄云下开变阴晴。","曜灵壮汝觜与距，外侮有犯乌维凭。","六龙顿辔或少轫，知有神物拥护终是阴为惩。","不然日围千里不一蓄，栖尔其内将何营？","及兹阴精盛，所历乖常经。","阳乌虽神力寡弱，势重不敌从侵凌。","避集扶桑枝，噤缩潜威灵。","想当既厄时，如何炎官赤熛不率其徒来助势与声。","彤幢绛天鼓雷霆，振乌挟日腾两翮，火吻喷薄摧阴凝。","逐兔入月胁，隐伏跧其形。","朴朔知所惧，弥离黯光晶。","含章合玄度，安曜周八纮。","天公此两目，万古更不盲。","嗟予既匪羲和官，区区空抱倾阳诚。","天高不可阶，此事难具陈。","作诗拟月蚀，欲见此志终或伸。","卢仝抚掌韩愈笑，吾等狂德君其邻。"]},{"t":"签院赵公许惠欧苏集作诗以问之","f":"七言古诗","c":["平生性癖耽坟籍，细字牛毛早年笔。","只今五十眼昏花，清昼看时满行黑。","投身散地百无事，不著书遮如有失。","赵公嗜书似邺侯，不为章句非雕搜。","绾持枢纽日多暇，借箸自有胸中筹。","更寻往事较所处，有梦不到琳琅璆。","嗟予何者登瀛洲，残膏未免窥前修。","奫然渊海鲛鳄翥，洞视千古苏韩欧。","文如不作作取法，舍是三子将谁求。","穷阎虽具何足玩，破碎熏黑支吟头。","牙签插架三万轴，谁省浙本铺银钩？","或苏或欧两俱可，勿使石璧成空投。","仁存义举侯门事，却恐乘机似巧偷。"]},{"t":"小边行一百五日同总尹张彦亨赴小边口相视河流回马上偶作此诗","f":"七言古诗","c":["北趋小边相河害，坐看长堤惊裂坏。","中流忽起刘子叹，疏浚神功思禹大。","忆当残金竟河界，两涯峡束如萦带。","灵鼍万鼓动地来，汹汹声闻千步外。","堤防不议四十年，河行虚壤任徙迁。","乃今去京无一舍，冲波南卧翻鲸鳣。","今年筑堤捍渰水，明年卷扫防洄渊。","涛头况与酸枣直，南北高下尤相悬。","既非经渎久远计，徒费民力妨农田。","正有避移策上闻，放之旷野从奔冲。","不然建议以土湮，大堤缕水横西东，楗以木石束逾钟。","递河东去过京角，此是永逸无穷功，作诗拟达宣房宫。"]},{"t":"梦陈节斋","f":"曲","c":["花枝入帘春梦香，游丝翻空清昼长。","今年寒食客梁苑，追忆往事心彷徨。","前年考试登兹堂，陈侯馆予罗酒浆。","拊床高咏逸兴发，不觉灯前大雨声淋浪。","生平胸臆向予尽，使我肝胆争开张。","重来物是人不复，夜梦见之昼微茫。","谁期此会乃死别，刬血不灭吴云苍。","揽衣起行步落月，梅影满庭空断肠。"]},{"t":"滹沱流澌行","f":"七言古诗","c":["王郎何人著柘黄，欲与赤伏争翱翔。","汉炎中断天复炽，肘后顽石胡为光。","萧王挥戈指幽蓟，战血满野风尘苍。","募兵返得市人噱，当时南驰亦苍皇。","鸢鞮城东滹水长，北风烈烈天雨霜。","前驱候骑两失色，河虽流澌无可航。","兔肩麦饭未下咽，大冰横合坚于梁。","古称王者阨不死，淮陵一言殆天使。","赤龙已渡凌四开，白鱼跃舟未逾此。","坛亭王气如水清，妖彗邯郸死灰耳。","彼苍有意开真主，固令若辈先驱处。","君看陇蜀最健者，一旦等蛙终汉虏，王郎区区安足数。","苍茫此日龙华渡，漠漠野烟生绿树。","留在长河阅世人，万古朝宗浩东骛。"]},{"t":"义侠行","f":"曲","c":["君不见悲风萧萧易水寒，荆轲西去不复还。","狂图祇与蝥蛛靡，至今恨骨埋秦关。","又不见豫让义所激，漆身吞炭人不识。","劘躯止酬一己恩，三刜襄衣竟何益。","超今冠古无与俦，堂堂义烈王青州。","午年辰月丁丑夜，汉允策秘通神谋。","春坊代作鲁两观，卯魄已褫曾夷犹。","袖中金锤斩马剑，谈笑馘取奸臣头。","九重天子为动色，万命拔出颠崖幽。","陂陀燕血济时雨，一洗六合妖氛收。","丈夫百年等一死，死得其所鸿毛輶。","我知精诚耿不灭，白虹贯日霜横秋。","潮头不作子胥怒，地下当与龙逢游。","长歌落笔增慨慷，觉我发竖寒飕飕。","灯前山鬼忽悲啸，铁面御史君其羞。"]},{"t":"入奏行美圣政而重民急也","f":"曲","c":["君不见燕南饥民行且泣，膏泽屯来三百日。","蚕沙齧尽木皮空，剉末草根充糗食。","追胥星火县帖严，官不汝怜需税石。","人生乡土孰不恋，一殍迫临那得惜。","扶羸载瘠总南逋，鹘面鸟形犹努力。","比之坐毙不相保，趁熟庶几延旦夕。","刑司府解两虚文，道路无言空叹息。","吾皇德并唐虞圣，轸虑斯民期日靖。","传闻一介或可相，不问草茅分政柄。","因思治道责有归，未洽鸿熙臣下病。","才丰禄秩即患失，又以材疏难仰称。","蹲而不去噤无声，老凤饥乌同一證。","西台入奏沃渊衷，蹴踏群疑开善政。","尽蠲秋赋出御女，百色支供皆省并。","若稽黄屋帝尧心，一语乂安无不听。","万方欢喜声一概，远过汉家宽大令。","三钱斗米说开元，二税户除闻大定。","限田固是平世法，未免区区与民竞。","况今江淮岁入数不赀，经画有方财恐剩。","人和天地气自舒，一雨行随明诏应。","老癃扶杖愿少留，又赖鸿恩拯县罄。","两河千里麦青青，预贺有年天子庆。"]},{"t":"紫藤花歌","f":"曲","c":["竹宫琐窗云雾垂，紫藤花发何葳蕤。","仙家驻景出异供，横掩桃李无晶辉。","群蛟奋蛰力犹困，鳞鬣不耐凄风吹。","天孙夜掷紫霞被，满意下覆须春曦。","幽禽缩喙不敢啄，囚锁恐泄苍精机。","又如王恺紫丝障，誇雄斗侈光陆离。","倒冠落佩众宾醉，临风零乱千缨緌。","虬柯扶疏散苍翠，季伦击碎珊瑚枝。","青宫宾客今园绮，杖藜来扣仙人扉。","遥惊紫艳翻半空，造物乃尔争新奇。","君不见香山老居士，梦与元九神交驰。","觉来清吟增怅望，紫桐花下空怀思。","何如吾侪时燕集，对床话久藤阴移。","兴馀属我扫笺素，烂柯不著山间棋。","刺檐入户要学腾蛟螭，鸟归花落香下来，时集毫彩沾人衣。","一杯春露助香润，清气贮满诗人脾。","依依青袅厨烟起，好命庖人办新美。","炷香供具祷群龙，莫学痴藤蟠未已，燕南饥民饥欲死。"]},{"t":"滹沱秋涨行","f":"曲","c":["君不闻蒙庄说秋水，两涘犹见马与牛。","今年滹沱水大涨，墟落濈濈生鱼头。","云蒸老雨注万壑，上不少止下可忧。","冯夷不受土所制，黑浪怒蹴鼋鼍游。","望洋东视誇海若，似愤蛙比跳跃井坎湫。","金行气肃坎宜缩，狂澜不逐西风收。","东行我济小范口，水势淼漭方淫流。","秋禾尽为鱼鳖饵，庐舍漂荡迷田畴。","二年旱暵例乏食，彼稷幸得逢今秋。","嗟哉一饭到口角，渰没无望将谁尤。","河防久废不复古，惟预揵治为良筹。","翻堤决岸势不已，虽有人力谁能谋。","近年遇灾幸无事，其或成患徒嗟诹。","两河农民被灾者，逃避无所栖林丘。","夜深投宿闻聚哭，悲声暗与虫声啾。"]},{"t":"平原行","f":"七言古诗","c":["羯奴骋兵伤滥恩，天宝之祸将自焚。","三郎宫中略不省，履霜有戒知何人。","平原蹇蹇真王臣，沈虑久识幽营氛。","泛舟从酒运奇略，一日楼橹惊云屯。","铁舆南来从猎火，河朔风靡烟尘昏。","孤城平地独与抗，勇鼓义旅争鲸吞。","西开土门掎蛇阵，南激睢守遮厓垠。","滔天腥秽思一扫，誓与此羯不两存。","书生信能立大事，竟掣贼肘西南奔。","事虽旷代有足感，鲁公之义世所尊。","我来吊古增永慨，苍烟草树连荒闉。","欲寻遗庙不复见，宝刻留在东方珉。","栖盖亭前野日曛，平原城下酹忠魂。","朝廷何尝容直道，志士蹈难甘捐身。","此心自视无愧已，一时知否非所论。","嗟予何者敢跂慕，屡书不厌枭鸾分。","当年纪载两鬼域，九泉奄奄随埃尘。","先生一死固不朽，雅操何翅同松筠。","故应烈日秋霜气，千古堂堂凛若神。"]},{"t":"华不注歌","f":"曲","c":["齐州山水天下无，泺源之峻华峰孤。","秦鞭有力驱不去，天遣一柱标齐墟。","初疑太素女娲氏，补天断手兹遗馀。","又如翠凤翥郊薮，来应世瑞开昌图。","南山连络虽可爱，未免阿附相承趍。","孤撑直上夹右碣，猛视又似天门貙。","庆封齐豹两元恶，哆齧犹露雄牙须。","不然齐太史，冤血凝碧老不渝。","化成直笔插天外，堂堂使表春秋诛。","乾坤乃有此雄跨，未许鹊药争头颅。","江山胜概尽轩豁，远客吟眺增踌躇。","李白上天不可呼，云烟变化何须臾。","后人摹写觑天巧，百匝空绕青芙蕖。","文章李杜光燄在，有诗无诗将何如。","我思齐晋迭雄长，山灵枉被兵埃污。","桓公九合犹霸事，三周其下真誇谀。","会须扶策凌绝顶，望入苍梧叫帝虞。"]},{"t":"椒兰怨","f":"曲","c":["昭皇迫东迁，望绝忠臣援。","堂堂雁门兵，祗足速祸变。","帝酣长星杯，醉魄迷椒殿。","神龙失水几上肉，恶枭啄门夜漏半。","龙兴赤雾天为红，一竁三百皆皇宗。","唐家大业至此尽，自古亡国未有若此之哀恫。","梁王归罪将谁给？","奴辈虽诛天有在。","金祥殿空杀气高，贼圭白刃专相待。"]},{"t":"汜水行","f":"曲","c":["五季权在兵，逆顺系财贿。","同光当宁能几朝，牝鸡司晨倾内外。","添都买宴物山积，尽入掖庭充内费。","君王政荒优宦狎，将相无辜恣诛杀。","蜀资百万贼所徼，纵有其能供近渴。","一夫夜呼汜水东，绛霄楼头兵反攻。","雍陵竟堕所好死，英武杳逐仙音空。","先皇有识如相问，三矢虽还未克终。"]},{"t":"通漕引","f":"七言古诗","c":["汉家鼎定天西北，万乘千官必供亿。","近年职贡仰江淮，海道转输多覆溺。","东阿距泉二百八，瀹济西来与清合。","安流取直民力省，积水浮纲才两闸。","自昔河防争横议，秖办薪刍不胜计。","宣防瓠子至今悲，以彼方兹功极细。","役徒三万期可毕，一动虽劳终古利。","裹粮荷锸去莫迟，行看连樯东过蓟。","休说春潭得宝歌，长笑韦郎空侈丽。","从今粒米斗三钱，狼藉都城乐丰岁。"]},{"t":"李夫人画兰歌","f":"楚辞体","c":["清閟堂深不知暑，瑶草佳期梦玄圃。","孙郎笑折紫兰来，素影盈盈映修渚。","李夫人，澹丰容，天然与兰相始终。","剡藤一笔作九畹，落墨不减江南工。","芳姿元与凡卉异，晔晔况是湘累丛。","离骚不复作，遗恨千古沈幽宫。","君看此花有深意，似写灵均幽思悲回风。","君家大雅堂，文彩东野翁，并入惨澹经营中。","秋风拂帘秋日长，芳霏霏兮汜崇光。","淡妆相对有馀韵，画栏桂子空秋香。","淡轩托物明孤洁，五十年来抱霜节。","固知色相皆空寂，妙得于心聊自适。","仿像湘娥倚暮花，黄陵庙前江水碧。","生平佩服真赏音，升闻紫庭非素心。","唤起谪仙摇醉笔，为翻新曲泻瑶琴。"]},{"t":"清霜怨","f":"曲","c":["日落偶过吴郎家，入门两阑姚魏花。","金盘洗妆都几日，已觉鬓乱钗横斜。","韩卿秉烛惜佳丽，便恐翠袖倚竹空春华。","鹤翎红糁玉蝶粉，堕髻睡美吴宫娃。","我欲问花不解语，何故忽尔令人嗟。","东皇醉著初不问，青女潜妒飞银沙。","花神敛袂避阴惨，驻颜何有仙人砂。","京师各圃花不少，今岁閒杀游春车。","客怀岂独被花恼，俗事扰扰惊无涯。","西风巷陌尘障面，酒楼寂寂空箫笳。","我因未事得閒在，尽日饮客前溪芽。","天教世务不挂口，遮眼幸有诗书葩。","时时弄笔散幽滞，钱裹忘计东坡叉。","为花作谱见衰盛，自笑思涩颐空呀。","因声寄谢紫山老，落落高举凌青霞。"]},{"t":"湘中后怨至元十八年岁辛巳冬十月按事顺德晨起灯下读沈下贤文集偶赋此或云郑即子春也","f":"七言古诗","c":["洛桥晓月光朦胧，彼姝娇啼桥水东。","郑生早发与之遇，挈去媵御甘长终。","雾绡烟縠已惝恍，《九歌》《招魂》皆楚风。","一朝谪满与郑诀，云是蛟娣非凡庸。","岳阳楼高花映红，满筵歌舞鲛人宫。","海风吹散歘不见，倚云望入湘江空。"]},{"t":"春夜宴史右相宅","f":"五言古诗","c":["勋阀汾阳业，金貂汉相家。","阳春元有脚，玉度瑩无瑕。","神骏推宛马，跳梁笑井蛙。","相逢成夜集，畅饮厌流霞。","绮席围声妓，银筝合凤琶。","晚妆添粉黛，杂舞见渝巴。","炉暖融螺甲，盘香供露芽。","透空敲雨杖，促节掺渔挝。","侑食增阳盛，纾怀发兴赊。","旧声今渐远，新体此无加。","楼转三更月，灯垂半夜花。","歌长萦曲调，狮猛奋须牙。","辞谢宁容退，留连暂乐佳。","直须穷薄伎，尤异是雄蹅。","登踏寒林判，轩呈迓古丫。","侍筵更纪仆，归烛黯笼纱。","下客陪簪玉，清吟拥鼻瓜。","嗣侯非自乐，先业念无涯。","待士无疏密，筹边静噪哗。","有时陈乐籍，张宴为宾嘉。","此夕真仪凤，明朝等散鸦。","宠光需北阙，春礿动南衙。","岂特调银字，重看拜白麻。","转头虽契阔，后话足雄誇。","碧草伤淹赋，清江吊屈沙。","别怀增惓惓，独雁谩哑哑。","霄汉嗟垂翼，庭阶愧倚葭。","情悠天共远，心在地无遐。","会作登楼客，聊停泛斗槎。","朱门三十载，未分鬓空华。"]},{"t":"谒武惠鲁公林墓四十韵","f":"五言古诗","c":["金驭成阴朽，山东自古强。","限田标镇戍，积愤致抢攘。","武惠当年杰，天心霸业匡。","云龙时际会，风虎日翱翔。","五十连城重，三千战士良。","一朝归版籍，遗爱在耕桑。","甫定先文治，来威戒伐张。","俭恭希大帛，号令肃秋霜。","气革耰锄扰，风还礼义乡。","颂方歌鲁盛，人骇陨星镗。","云出青崖顶，乌瞻泰岱傍。","驱车经鹊里，故宅似汾阳。","山倚祁连冢，祠荒绿野堂。","门旌虚将幄，燕寝尚清香。","有客追畴昔，怀人动慨慷。","王师初破汴，河朔久沦纲。","文物随云散，招徕不一亡。","尽收周礼乐，重辟汉科场。","清秩铨华省，群英萃郡庠。","有金皆冶器，无玉不追章。","蓄德需明主，流波及四方。","星躔从落落，奎彩独煌煌。","嗣相图光绍，先猷在益彰。","雪山宜久重，世业浸丕昌。","帝道开中统，皇风煽八荒。","重推黄阁相，轻是尚书郎。","两署分荷橐，千官列雁行。","至今称济济，所在见跄跄。","原治无多术，推贤用叵量。","措材真得所，收效尽非常。","侯国能如此，朝家化更皇。","阐明虽实理，勉励乏明扬。","一代徐通议，中流号巨防。","试图援手助，潜有跋胡妨。","薄宦新过鲁，诸生惧面墙。","泮田饶乐育，师授奈无望。","可惜弦歌地，虚成笱在梁。","力扶虽切切，事迫去遑遑。","量分功名薄，伤时涕泗滂。","野烟知客恨，先自柏城苍。"]},{"t":"灵岩寺二十六韵","f":"五言古诗","c":["中土论名刹，兹山第一岩。","地灵连海岱，境胜隔仙凡。","绀殿通虚阁，丹崖间翠岚。","天低神宝岭，佛出證明龛。","鸡警阴魔暴，僧驯怒虎眈。","定师兴寺始，党刻不辞惭。","石状殷公怪，眉庞老衲毵。","钟声盘绝壑，幡影走枯楠。","法护双椤树，经严七宝函。","巢栖松鹤赭，茗瀹露泉甘。","花雨濛沙界，岩团抱碧潭。","布金仍赵魏，仰食不耕蚕。","富览山无尽，幽寻力不堪。","微官嗟缚律，小隐欲投簪。","吟就篮舆往，禅思玉版参。","静缘天或假，世味苦相谙。","城市蛙居坎，功名蚁战酣。","有来求福利，谁复减嗔贪？","风化吾儒在，慈恩释氏覃。","教崇缘世主，风靡过周南。","以此山林胜，皆为佛老探。","兹游聊适意，他日尽横谈。","翠琰诗如此，清吟口讵缄。","顾瞻因咄咄，前后至三三。","山主留昏宿，官程畏众碞。","夕阳人影淡，犹惜动归骖。"]},{"t":"送李郎中德昌北还情见乎辞","f":"五言古诗","c":["一自新河别，经今已十年。","为寻江表传，重会岭南天。","鸿鹄乘风健，骅骝得路先。","鸡香芬省署，襟谊动星躔。","洒落生平契，留连祖送筵。","自嗟衰病客，愁卧瘴江烟。","岁月邻期耄，乡关近五千。","依依枝绕鹊，跕跕水飞鸢。","外望何其切，中坚未易镌。","崇高畴弗恋，筋力若为前。","落日乡音杳，秋空望眼穿。","委心歌已矣，适意俟终焉。","行止虽存数，周旋正赖贤。","省台公道在，万一故人怜。"]},{"t":"番禺杖","f":"五言古诗","c":["异种来番国，知名自老坡。","杖才任操倚，节目喜摩挲。","尺度天然足，柑黄气色和。","奇姿含海雾，孤植映江沱。","物眇离乡贵，材稀审实讹。","声音铿爪甲，鳞介讶鲛鼍。","鞭驭真雷策，批亢格鲁戈。","重轻欣得所，长短称闲拖。","扶老携行便，持危得力多。","金蛇僵自劲，鲐背痒忘苛。","不自浮槎使，来从老伏波。","见归情郑重，未许老婆娑。","入手嗟神物，传看骇玉柯。","支颐看月出，横膝伴诗哦。","选胜寻泉石，穷幽入薜萝。","有时儿女触，却恐鬼神呵。","盖节空筇竹，神锋黯太阿。","笑挥堪解虎，静倚可降魔。","灵寿轻无赖，梅条皱可捼。","花藤昏玳晕，斑点惨湘娥。","桃竹那能比，桃榔未足歌。","望尘甘却立，敛迹总无过。","用舍时当审，敲撞责果何？","更防雷雨夜，冲屋学陶梭。"]},{"t":"题常仁卿运使西觐纪行二首 其一","f":"五言律诗","c":["九万鹏抟翼，孤忠驾使轺。","功名元有数，风雪不知遥。","抵北踰鳌极，维南望斗杓。","胡生摇健笔，且莫诧东辽。"]},{"t":"题常仁卿运使西觐纪行二首 其二","f":"五言律诗","c":["三策条民便，逾年致节旄。","梦惊羊胛日，崄历幻人刀。","碧盌昆坚异，黄金甲第高。","白头书卷里，留滞敢辞劳。"]},{"t":"秋夜","f":"五言律诗","c":["卧榻铺筠簟，风檐递晚凉。","云枯涵旱气，星烂射寒芒。","钟鼓寒更永，乾坤夜色苍。","时危关百虑，低首拊空床。"]},{"t":"星子镇道中","f":"五言律诗","c":["北下星关道，川开百里宽。","梦残倾锦帢，吟细缓征鞍。","土峡深回洞，山田叠醮坛。","一杯亭传酒，来为敌霜寒。"]},{"t":"田间","f":"五言律诗","c":["斜日秋瓜圃，云间雨过初。","平畴交晚吹，凉意满轻裾。","草木浮元气，河山拥草庐。","拊心欣有得，重展故人书。"]},{"t":"午憩阳城北龙泉寺","f":"五言律诗","c":["倦客鞭催急，龙泉一解鞍。","在家贫亦好，行路古来难。","寺古松杉老，山空水石寒。","万松亭废久，重拂短碑看。"]},{"t":"清苑道中","f":"五言律诗","c":["野店春风里，行人避绣衣。","剑华寒有晕，山日惨无辉。","孤隼梢云下，群鸦结阵飞。","惊鸥无远泛，事外本忘机。"]},{"t":"辞长乐先垄","f":"五言律诗","c":["展墓过农里，衔恩使远方。","气随天北转，人与雁南翔。","肝胆孤忠在，江湖去路长。","此回当自信，不必泥行藏。"]},{"t":"望舍弟消息","f":"五言律诗","c":["忆弟居穰县，嗟予宦建阳。","三书曾未报，一别谩相望。","喜信占晨鹊，清吟梦夜床。","残年能几许，长与汝参商。"]},{"t":"高邮道中","f":"五言律诗","c":["筑甬馀三百，湾环护漕沟。","重桥穿宝应，一岸入高邮。","水陆开亭转，烽烟静塞愁。","腰缠无十万，官遣上扬州。"]},{"t":"望岭","f":"五言律诗","c":["溪岭无千里，崎岖半月间。","事机须勇退，天意许生还。","顺处从多厄，趋时免强颜。","越禽忻我往，长路语关关。"]},{"t":"首夏家居即事二首 其一","f":"五言律诗","c":["懒帻从鬅鬓，披衣任曳裾。","都忘身外事，贪读意中书。","比老心能尔，虽贫乐有馀。","绕园欣细履，树影绿扶疏。"]},{"t":"首夏家居即事二首 其二","f":"五言律诗","c":["竹茂资泉润，花荣藉圃沙。","钩帘来舞燕，锁树护栖鸦。","客至留酤酒，吟长待煮茶。","几时容却扫，一向似仙家。"]},{"t":"和仲常牡丹诗","f":"五言律诗","c":["汉殿承恩早，金盘荐露新。","色酣中省乐，香重锦窠春。","尽殿群芳后，谁辞载酒频。","清如司马相，也作插花人。"]},{"t":"大行皇帝挽词八首 其一","f":"五言律诗","c":["滦水龙飞日，长杨羽猎时。","天颜凡五见，雨泪遽双垂。","化日中天赫，阴灵万国驰。","何由知帝力，耕凿乐雍熙。"]},{"t":"大行皇帝挽词八首 其二","f":"五言律诗","c":["威破群雄胆，恩藏四海心。","声明三五盛，垂拱九重深。","国论多儒断，天机入睿临。","小臣剺面血，无路洒松林。"]},{"t":"大行皇帝挽词八首 其三","f":"五言律诗","c":["去岁回銮辂，旌麾拥万灵。","今春辞画翣，弓剑閟泉扃。","黼扆虚琼岛，云龙惨帝庭。","词臣思补报，泪湿简编青。"]},{"t":"大行皇帝挽词八首 其四","f":"五言律诗","c":["帝系三宗上，麟经一统尊。","火盘承正据，虎落入雄吞。","穷蹴南交兽，奔腾北海鲲。","不教擒一索，遗恨付皇孙。"]},{"t":"望淮","f":"五言绝句","c":["朝日惨无色，昏昏水气间。","到淮犹数里，隔岸见尖山。"]},{"t":"夏夜","f":"五言绝句","c":["庭竹影扶疏，清风晚骚屑。","夜凉人未眠，卧看窗间月。"]},{"t":"梦中得","f":"五言绝句","c":["持酒濯利剑，青蛇光黯然。","金鞭鞭骏马，汗血沾锦鞯。"]},{"t":"披襟","f":"五言绝句","c":["凉风东北来，荡尽中夜热。","起视河汉星，微云淡明灭。"]},{"t":"送王嘉父","f":"七言律诗","c":["新知虽乐道弥亲，樽酒灯前便故人。","时宦尽从间处著，浩歌还爱醉时真。","红莲幕府名兼隐，春草池塘句有神。","恨煞百门山下水，锦波流不到东秦。"]},{"t":"清明日锦堤行乐","f":"七言律诗","c":["浪说兰亭褉事修，年年春好锦堤游。","花翻舞袖惊歌板，柳隔高城暗酒楼。","绿树恐应春事老，金鞭重为使君留。","竹西路晚归时醉，何处珠帘半上钩。"]},{"t":"南城纳凉晚归","f":"七言律诗","c":["书院归休日已曛，南城风细晚相亲。","坐来近市喧初息，归到衡门夜向分。","矮榻趁凉欣稚子，疏灯留影伴厨人。","一杯粥了从高卧，须信閒身等策勋。"]},{"t":"送萧四祖北上","f":"七言律诗","c":["丹凤衔书下紫庭，秋宵光动少微星。","蒲轮再起秦遗逸，天意将新汉典刑。","长策正劳黄屋梦，故山从使白云扃。","中原有幸经纶了，天外高鸿本自冥。"]},{"t":"雨中与诸公会饮市楼","f":"七言律诗","c":["每恨人生会合难，兴来一醉尽君欢。","雨沾翠佩帘花细，酒凸金杯饮兴宽。","《胡旋》舞低翻翠袖，串珠喉稳怯春寒。","朝来酒醒蓬窗下，依旧春风苜蓿盘。"]},{"t":"自适","f":"七言律诗","c":["旋收柏实炷炉薰，纸帐低垂自有春。","竹几隐眠无俗梦，蒲团容膝胜华裀。","窗间白日惊涛迅，门外黄尘万事新。","幸与圣贤相晤语，未辞藜藿此生贫。"]},{"t":"哀故宫","f":"七言律诗","c":["掖庭依约粉垣丹，行入荒宫重黯然。","华表忽惊人世换，昆明重见劫灰寒。","石龙委地埋秋草，湖玉临池倚暮烟。","满目悲风吹酒醒，东华门外泪阑干。"]},{"t":"登凌云阁","f":"七言律诗","c":["布衣尘满戴儒冠，风袂来登上将坛。","栋藻云飞朱栱湿，檐牙霜重玉梯寒。","风烟远胜筹边迥，气势雄吞汴水乾。","经略江淮有成算，不须重展地图看。"]},{"t":"铜台怀古","f":"七言律诗","c":["都邑盘盘据四冲，登临形势觉天雄。","歌楼暖响春风细，绮陌香销宝气空。","笑著孱王承宋弊，至今奸孽擅唐终。","凭高谁识神州恨，付与衡漳日夜东。"]},{"t":"镇州怀古","f":"七言律诗","c":["赵武雄图不可寻，风烟东接九门深。","炎凉到此分南北，战伐无情自古今。","弹蹑流风犹战国，椎埋遗俗带燕音。","剑歌不遇平原客，落日滹沱动旅吟。"]},{"t":"燕城书事","f":"七言律诗","c":["都会盘盘控北垂，当年宫阙五云飞。","峥嵘宝气沈箕尾，惨淡阴风贮朔威。","审势有人观督亢，封章无地论王畿。","荒寒照破龙山月，依旧中原半落晖。"]},{"t":"夏日南堂即事","f":"七言律诗","c":["一雨清凉恰四朝，雾丝萦户见蟏蛸。","病因戒酒成真止，辞免书门绝妄交。","道拙尚忧儿坠简，家贫且喜稼盈郊。","间庭绿藓泥融遍，燕子飞来补旧巢。"]},{"t":"送王子初总管奉诏北上","f":"七言律诗","c":["圣代崇儒意匪轻，徵车相望半诸生。","九天雨露思贤相，十载经纶见老成。","更化有方先定制，救时无验是虚名。","烟霄未遂攀鳞志，葵藿空怀向日诚。"]},{"t":"开平晚归","f":"七言律诗","c":["龙首冈边野草深，秋风滦水动归心。","百年蓬巷开圭窦，一日恩光照士林。","吟鬓有光浮镜玉，家书封喜认泥金。","料应晓月帘栊底，乾鹊飞来报好音。"]},{"t":"赋西域鹦鹉螺杯","f":"七言律诗","c":["老月沦精射海波，珠绳分秀贯神螺。","鹧斑渍粉垂金薤，鹦喙嫌寒缩翠窠。","樽出瘿藤纹浪异，瓢成椰子腹空皤。","饮馀疑与溪娘遇，一笑相看发浩歌。"]},{"t":"宛叶道中","f":"七言律诗","c":["六合云蒸一气霾，漫漫长路渴生埃。","诗从白雨明边得，人自青山尽处来。","世路有机难预料，剧谈供笑不时开。","济时赖有诸君在，汉苑秋风愧不才。"]},{"t":"次宿汝楼韵","f":"七言律诗","c":["微云河汉半晴阴，夜景萧森梦化城。","山色不随乔木老，月华偏对故人明。","鹤缘露警清无寐，蛙属官居重有声。","廊庙只今纷治具，正容坚坐看升平。"]},{"t":"临武堂宴醉后有怀省台诸公","f":"七言律诗","c":["桂月流光雪满台，月明人影两徘徊。","行云不逐歌尘散，往事还随去雁哀。","双鬓入秋无可白，寸心于世未全灰。","遥怜红药阶前客，玉树相依一笑开。"]},{"t":"夏县道中","f":"七言律诗","c":["湿云压树际岗平，溽暑还因小雨增。","官事困人如缚虎，秋风吹野梦翻鹰。","趋时未必儒冠误，并隐端为野鹤憎。","遥忆筠溪亭下水，万竿苍雪照吟灯。"]},{"t":"饯陈签省行台西夏","f":"七言律诗","c":["汉家威德际髦蛮，牙孽其中虑阻艰。","金节远开丞相府，春光先渡玉门关。","正烦烟火通青海，未用梯航致白环。","银字诏还知不远，好来弹压紫宸班。"]},{"t":"题赵宣抚樊川山中杂咏","f":"七言律诗","c":["苍崖如削静烟霏，中有高人住翠微。","夜鹤听琴依蕙帐，晓泉和月落山扉。","一龛静体炎凉理，两眼深明倚伏机。","毕竟名高难久卧，野猿偷褫芰荷衣。"]},{"t":"至元七年庚午奉陪宪台诸公阙下贺正口号","f":"七言律诗","c":["盘盘帐殿敞彤庭，天仗宵严拥万灵。","玉笋东班分列辟，龙墀首拜认前星。","烟蟠鳌柱沾吟袖，乐泛仙音近御屏。","岁岁大酺恩例溥，自惭虚薄仰皇扃。"]},{"t":"同马才卿暇日登昊天寺宝严塔有怀","f":"七言律诗","c":["高标直上跨苍穹，物外方知象教雄。","九陌市声开晓色，两都乔木动秋风。","遥怜汉马屯湘渚，安得长书附塞鸿。","寂历村墟野烟外，谁家帘幕夕阳红。"]},{"t":"追挽元遗山先生","f":"七言律诗","c":["文奎腾彩忆光临，孺子何知喜嗣音。","党赵正传公固在，阳秋当笔我奚任。","天机翻锦馀官样，月户量工更苦心。","野史亭空遗事坠，荒烟埋恨九原深。"]},{"t":"西苑怀古和刘怀州景融韵","f":"七言律诗","c":["彩凤箫声彻晓闻，宫墙烟柳接龙津。","月边横吹非清夜，镜里琼华总好春。","行殿基存焦作土，《踏锥》舞歇草留裀。","野花岂解兴亡恨，犹学宫妆一色匀。"]},{"t":"糟鱼","f":"七言律诗","c":["霜刀截断玉腴芳，暖贮银罂酿粉浆。","锦尾带赪传内品，金盘堆雪喜初尝。","解酲未减黄柑美，隽味能欺紫蟹香。","一箸餍馀乘醉卧，梦横沧海听鸣榔。"]},{"t":"山阳偶与大继长相遇自辛亥年相别至今廿八年矣追念畴昔作诗为赠","f":"七言律诗","c":["解鞍林下振清埃，怀抱樽前得好开。","白发满头心事在，青山当眼故人来。","风流自有高贤识，感慨还深漂母哀。","读尽深香转萧爽，清吟不到伯伦台。"]},{"t":"种玉亭","f":"七言律诗","c":["灵沼云深宝气存，素蘤一夕发芳根。","烟中髣髴溪娘语，波面轻盈越女魂。","江月借妆增皓彩，露华和屑贮芳温。","夜深更待瑶环供，细挹秋香共一樽。"]},{"t":"桃花菊","f":"七言律诗","c":["泪洒明妃寄露葩，换根非为贮丹砂。","黄轻白碎空多种，碧烂红鲜自一家。","骚客赋诗怜晚节，野人修谱是头花。","九秋霜露无情甚，时约行云护彩霞。"]},{"t":"秋怀","f":"七言律诗","c":["醉头扶起日三竿，扫罢幽轩到药阑。","傍架整齐书帙乱，绕篱料理菊枝残。","日融虚阁留馀暖，雨积高空促早寒。","处置身心閒里过，不将勋业镜中看。"]},{"t":"丁亥岁十月十日夜梦乘船渡一大河既济望南岸一阁高数百尺窗户北向自檐至地上下以琉璃大帘垂蔽翠色半天甚奇丽也","f":"七言律诗","c":["云间高阁翠为帘，疑是仙居拥卫严。","虹影荡摇青帝阙，海风吹堕宝陀岚。","半空倒景惊奇绝，千丈摇光入顾瞻。","我自平生多异梦，似怜方朔诧雄谈。"]},{"t":"清明后一日雨中招林韩李三君子小酌且为梨花洗妆","f":"七言律诗","c":["花满金罍酒满樽，一杯欢饮得佳宾。","近年乐事无今岁，此际閒身有几人。","禄美胜于三品料，腊香清彻六根尘。","风檐数点催妆雨，办与梨花作好春。"]},{"t":"海棠","f":"七言律诗","c":["桃李无光分落英，海棠姿色占春荣。","云鬟绿拥妆初罢，醉脸红匀睡未醒。","任使无香真可意，放教千叶更多情。","光风流转都能几，莫惜沙头倒玉瓶。"]},{"t":"小园即事","f":"七言律诗","c":["小园清润稍堪观，翠有庭筠馥有兰。","未放蔷花金作蕾，已开梨蕊雪为团。","鸟欣有托扶疏树，客喜来凭诘曲阑。","深院日长须细履，也胜愁坐两眉攒。"]},{"t":"仪封道中","f":"七言律诗","c":["驿馆残釭曙色分，马驮残梦走踆踆。","去家已远谁为侣？","到处相逢有故人。","健羡雕盘惭始击，静便蠖蛰返求伸。","一杯拜酹睢阳庙，激懦扶衰尚有神。"]},{"t":"西湖","f":"七言律诗","c":["西湖三面簇青山，净拭菱花照翠鬟。","苍海月寒龙穴露，彩云仙去凤箫閒。","无多楼观犹图画，最好风烟近市阛。","郑重绣衣周漕使，画船春酒待予还。"]},{"t":"三山元日","f":"七言律诗","c":["台爇天香簇绛纱，三山箫鼓乐年华。","竹枝歌后多淫祀，燕子归来识故家。","荷鬓闹妆馀翠贝，蔬盘匀饤杂鱼虾。","殊方风物虽堪赏，争遣衰年客海涯。"]},{"t":"近读夜永不寐等作觉清而颇寒吾恐伤中和而病吾子也因复继前韵假辞而薰炙之亦晁补之拟骚之遗意也","f":"七言律诗","c":["烛影红摇夜色侵，香添菱叶郁重衾。","凤琶调软歌能合，竹叶杯深醉易沈。","绿鬓追欢燕市乐，翠屏归梦越江吟。","平明剩买扶头酒，不向诸儿计橐金。"]},{"t":"佛狸祠","f":"七言律诗","c":["江山照眼舒清眺，千古兴亡堕眼前。","瓜步市长连野戍，佛狸祠古惨荒烟。","柁楼看取平吴日，父老空传饮马年。","此日不须开浊浪，好风都属往来船。"]},{"t":"琉璃肺","f":"七言律诗","c":["击鲜为具乐朋簪，辣品流馨涨绿沈。","犀箸喜辛忘海味，霜刀争割快牛心。","四筵谈屑霏馀烈，一缕冰浆濯□襟。","胜过屠门矜大嚼，梦云飞绕蹛林深。"]},{"t":"题香山寺画卷","f":"七言律诗","c":["送客当年过玉泉，醉中游赏得奇观。","一泓湛碧浮僧钵，几叶秋黄打石阑。","山色空濛金界湿，松声清泛海波寒。","吟鞭回首都门道，斜日归时翠满鞍。"]},{"t":"送舍弟南归穰下","f":"七言律诗","c":["相思渭北常年事，远送漳南恨别心。","沙暖暂联鸿雁序，霜寒凄断鹡鸰音。","两乡健在都能几，千里含情老更深。","慰浣此怀知恳切，不教消息到浮沈。"]},{"t":"德寿殿玉方池砚","f":"七言律诗","c":["玉斲坤形霮四溟，丹书犹认寿宫名。","纷纷落墨腾蛟雾，淅淅秋风拉瑟声。","神物不知昆火烈，碧丝今对玉堂卿。","眼中多少兴亡事，白发孤臣最怆情。"]},{"t":"送总统佛智师南还","f":"七言律诗","c":["白足毗耶不易逢，鬓丝禅榻偶相同。","经来震旦三千界，人在天龙八部中。","满送酒船浮北海，细薰香雾供南丰。","江东父老催飞锡，要沸潮音与海通。"]},{"t":"谢徐容斋赠梅","f":"七言律诗","c":["燕钗宫额蜡妆匀，梦绕罗浮雪里村。","持赠一枝遮老眼，淡依疏影度黄昏。","风流灯下佳人面，潇洒吟边竹叶樽。","我老忘情被花恼，曲屏深锁惜芳温。"]},{"t":"梦升天诗","f":"七言律诗","c":["沈沈玉漏三更后，鹏背扶摇九万抟。","彤管梦传江令笔，紫袍归抱上岩端。","苍溟赤日瞻天近，碧落银河照眼宽。","欲蹑帝关谁汝画？","九霄风露不胜寒。"]},{"t":"西池幸遇诗","f":"七言律诗","c":["射殿风清巳午间，曳裾挟策拜隆颜。","首询帝子龙楼召，喜辍犀弓偃月弯。","葵藿尽酬承日志，简编不负半生閒。","满樽春露沾恩处，光动西池玉笋班。"]},{"t":"洛中吟","f":"七言古诗","c":["万方文物洽尧雍，若论声明极洛中。","地自水南连洛北，治从真庙到神宗。","总将六合清明气，散作三川礼让风。","道统有传程邵在，勋名无比富文崇。","棚车载酒都人赏，名教传家习俗同。","花木四时春不老，耕桑弥野岁长丰。","三千步障家虽侈，十二行窝乐最融。","春酒泛香沽翠幕，夜花和露买筠笼。","小车高阁期真侣，魏紫姚黄擅化工。","爱育总归君父圣，论思不出庙堂公。","荆舒变法无期月，社稷垂亡到一空。","读罢适然清兴远，一帘花影晓光红。"]},{"t":"游琼华岛四首 其一","f":"七言绝句","c":["蓬莱云气海中央，薰彻琼华露影香。","一炬忽收天上去，谩从焦土说阿房。"]},{"t":"游琼华岛四首 其二","f":"七言绝句","c":["蹑尽寒云最上层，土花春碧梦觚棱。","江山如画人空老，更倚残阳望道陵。"]},{"t":"游琼华岛四首 其三","f":"七言绝句","c":["玉树歌声绕北虚，朔风吹恨入南都。","六鳌不戴三山去，留与都人泣鼎湖。"]},{"t":"游琼华岛四首 其四","f":"七言绝句","c":["光泰门东日月躔，五云仙仗记当年。","不烦细读江南赋，老树遗台倍黯然。"]},{"t":"梁园对月","f":"七言绝句","c":["儿时曾住汴梁城，二十年来重此行。","一片凤凰池上月，向人还似旧时明。"]},{"t":"夏夜","f":"七言绝句","c":["野云明处电飞光，海牵青浮落日黄。","想得近山多雨过，满庭风竹月波凉。"]},{"t":"春夜独坐","f":"七言绝句","c":["读书声歇烛华残，润入琴弦觉夜寒。","寂寞小窗云影薄，隔帘梧叶雨声乾。"]},{"t":"仙游曲五绝 其一","f":"七言绝句","c":["庭竹无人绿满窗，幽香和露湿霓幢。","日长孤绝坛边鹤，啄遍晴苔影一双。"]},{"t":"仙游曲五绝 其二","f":"七言绝句","c":["金简朝元拥玉华，碧壶香满谪仙家。","石坛冷挂银潢水，会待秋风送客槎。"]},{"t":"同刘劝农彦和葛县令祐之游苍谷口四首 其一","f":"七言绝句","c":["四山遮尽外来风，山崦人家不觉冬。","独立苍崖重回首，山形浑似入居庸。"]},{"t":"同刘劝农彦和葛县令祐之游苍谷口四首 其二","f":"七言绝句","c":["九龙分部中天雨，何处痴蟠睡不开。","一勺凤凰台下水，有时风雨洗天来。"]},{"t":"同刘劝农彦和葛县令祐之游苍谷口四首 其三","f":"七言绝句","c":["方山忽断两崖开，中有苍河自北来。","行出山门俱不见，玉龙翻作地中雷。"]},{"t":"同刘劝农彦和葛县令祐之游苍谷口四首 其四","f":"七言绝句","c":["地炉火在壁灯昏，睡觉山堂笑语温。","豆粥一盂官事了，缓摇吟辔出山门。"]},{"t":"游霖落山杂诗二首 其一","f":"七言绝句","c":["东山削出翠芙蓉，西壑䂘砑贮雪风。","人说魏王曾避暑，殿基犹是旧离宫。"]},{"t":"游霖落山杂诗二首 其二","f":"七言绝句","c":["滴乳岩前挂瀑流，青林飞洒动高秋。","玉龙跃入青冥去，堆叠苍烟万壑愁。"]},{"t":"游栖嵓寺三首 其一","f":"七言绝句","c":["翠嵓回抱郁苍官，绝境轩横杳霭间。","老矣瑞峰应健在，护持长伴八龙间。"]},{"t":"游栖嵓寺三首 其二","f":"七言绝句","c":["一径萦纡入杳冥，望川亭迥夕阳明。","欲知眼界宽多少，放出秦川似掌平。"]},{"t":"游栖嵓寺三首 其三","f":"七言绝句","c":["层岩重倚尚斜阳，山下风烟一漫苍。","恨煞爱山王老子，不来同宿赞公房。"]},{"t":"清明后一日作","f":"七言绝句","c":["懊恼春悰困宿酲，偶随游子到溪亭。","多情几行城南柳，三度春风见汝青。"]},{"t":"关山秋霁图","f":"七言绝句","c":["望京楼上晚凭阑，长记居庸八月还。","一段紫烟吟不尽，枉分秋色与南山。"]},{"t":"题张梦卿双清图","f":"七言绝句","c":["淡妆疏影两依依，点缀横斜画总宜。","恰似孤山篱落畔，小溪如练月如眉。"]},{"t":"禹庙","f":"七言绝句","c":["大地河山绣错明，野烟孤庙枕荒城。","杜鹃饶舌知何事？","血洒东风怨未平。"]},{"t":"泽潞即事杂诗三首 其一","f":"七言绝句","c":["自古徒兵泽潞雄，选齐尤见四州公。","堂堂气与鼙声壮，闪闪旗翻日脚红。"]},{"t":"泽潞即事杂诗三首 其二","f":"七言绝句","c":["角声催日上牙城，白羽风清坐阅兵。","盾鼻恐烦磨檄墨，莫教华发等閒生。"]},{"t":"泽潞即事杂诗三首 其三","f":"七言绝句","c":["一檄风驰万有降，天兵开国古无双。","寄声璧月琼枝客，铁锁休誇一苇江。"]},{"t":"游青莲寺","f":"七言绝句","c":["上方层阁倚晴烟，回合诸峰耸碧莲。","午枕不容诗梦就，天风吹雨下危巅。"]},{"t":"显宗墨竹","f":"七言绝句","c":["离离香粉淡争妍，莫作荒寒景趣看。","绝似承华宫槛畔，春风和露湿阑干。"]},{"t":"闻方响","f":"七言绝句","c":["丁东铿戛碎璆琳，掩尽朱弦窈眇音。","花外粉墙遮不断，佩环清彻洞房深。"]},{"t":"春江独钓图","f":"七言绝句","c":["渺渺春江碧若空，一丝斜袅钓坛风。","富春莫拟幽栖稳，已在君王物色中。"]},{"t":"题烟江叠嶂图","f":"七言绝句","c":["楚水吴山万里秋，风帆吹饱北来舟。","应怜满眼新亭客，空对江山双泪流。"]},{"t":"山行杂诗二首 其一","f":"七言绝句","c":["太行元气老洪濛，草树风前带润容。","山色只宜差远看，近移空翠上高峰。"]},{"t":"山行杂诗二首 其二","f":"七言绝句","c":["西来游宦半忙閒，六日迢遥道路间。","回转羊肠三百里，天教马上饱看山。"]},{"t":"毳幕卓歇图","f":"七言绝句","c":["牙旗风软马萧萧，渭水归来气更豪。","想得龙沙西北道，际天秋草黑山高。"]},{"t":"韩干画照夜白图","f":"七言绝句","c":["缨绂驺衣一色红，玉华光照苑门空。","昭陵六骏秋风里，辛苦文皇百战功。"]},{"t":"滕王蝶蚁图二首 其一","f":"七言绝句","c":["槐壤纷纷事暂欢，枕中栩栩伴周閒。","丹青欲识滕王意，须著人间比梦间。"]},{"t":"滕王蝶蚁图二首 其二","f":"七言绝句","c":["粉香金翠梦能甜，细写春悰入笔尖。","却恐寻香飞便去，六宫争下水晶帘。"]},{"t":"万寿节同宋太常弘道出左掖门口号五首 其一","f":"七言绝句","c":["禁漏穿花夜已央，宫槐笼晓色苍苍。","殷勤一点东华日，先到红鸾扇影光。"]},{"t":"万寿节同宋太常弘道出左掖门口号五首 其二","f":"七言绝句","c":["隔夜端门分板位，平明簪笏列鹓行。","紫云低覆千官拜，润入金炉百和香。"]},{"t":"万寿节同宋太常弘道出左掖门口号五首 其三","f":"七言绝句","c":["羯鼓声高吹管清，九天合作凤鸾鸣。","侍仪赞喝三成后，磬折齐呼万寿声。"]},{"t":"万寿节同宋太常弘道出左掖门口号五首 其四","f":"七言绝句","c":["花映岩廊近紫宸，宫官行酒过三巡。","共携满袖香烟出，散作都城十日春。"]},{"t":"万寿节同宋太常弘道出左掖门口号五首 其五","f":"七言绝句","c":["对品班分玉笋行，一时望拜殿西厢。","百官燕出宫闱静，疏雨濛濛湿建章。"]},{"t":"题乐天不能忘情图二首 其一","f":"七言绝句","c":["病来心事转蹉跎，身外犹嫌长物多。","况是春归留不得，侍儿无用蹙双蛾。"]},{"t":"题乐天不能忘情图二首 其二","f":"七言绝句","c":["青衫憔悴老江州，放逐归来万事休。","止有醉吟情未减，又翻新样柳枝愁。"]},{"t":"汴梁清明","f":"七言绝句","c":["连日风沙此日晴，东君有意作清明。","垂鞭醉入宫城去，一片伤心画不成。"]},{"t":"寒食日过隆德宫","f":"七言绝句","c":["当年陆海骇珍藏，此日繁华堕渺茫。","春草不随人事换，依然分翠入宫墙。"]},{"t":"宫井","f":"七言绝句","c":["清时瑶殿引瓶金，百尺还闻坠水音。","想得日长宫阁静，玉盘珍果看浮沈。"]},{"t":"武元直雪霁早行图","f":"七言绝句","c":["雪拥天山六月寒，冷云西北是长安。","行人马上扬鞭喜，犹胜南荒作热官。"]},{"t":"庚辰岁人日前一日书梦中所见","f":"七言绝句","c":["碧树翻香满洞春，一声长笛隔花闻。","似嫌燕语莺吟碎，暖喷宫音遏梦云。"]},{"t":"小桃","f":"七言绝句","c":["梅粉飘零柳未烟，一枝春色独当轩。","今年盼得红苞折，风雪禁持第几番。"]},{"t":"周文矩勘书图","f":"七言绝句","c":["宫槐阴合玉堂清，书叶翻香入细听。","内苑近来游宴少，太平天子要传经。"]},{"t":"楼居春望图","f":"七言绝句","c":["翠敛双娥底事愁，不缘春去落花稠。","归鞍未得朝天信，望断东风燕子楼。"]},{"t":"游百家岩杂诗","f":"七言绝句","c":["月池悬溜落苍洼，岩窦分居可百家。","不羡碧澜秋色好，倚天惊绝赤城霞。"]},{"t":"太一宫","f":"七言绝句","c":["庭树潇潇绿满廊，日长深锁碧窗凉。","隔帘遥见秋来处，一叶轻黄堕井床。"]},{"t":"玉堂闲适图","f":"七言绝句","c":["醉岸乌纱殿影东，宫花低映酒波红。","兴来草罢《长杨赋》，独占高槐洒晚风。"]},{"t":"庄宗横吹图","f":"七言绝句","c":["郭相西征奏凯还，阿娇欢宠镜交鸾。","却嫌暖殿春风燠，玉管横翻晓吹寒。"]},{"t":"细君崔氏哀辞二首 其一","f":"七言绝句","c":["去年扶病上新茔，歌管杯盘水曲亭。","今日重来人不见，杏花零落柳条青。"]},{"t":"细君崔氏哀辞二首 其二","f":"七言绝句","c":["兰枯蕙槁不禁风，一夕吹香入殡宫。","把酒试浇桥下水，不容将恨到湘东。"]},{"t":"润州","f":"七言绝句","c":["望空北顾无双寺，行入西津第一州。","江影隔山摇素练，行云和梦锁朱楼。"]},{"t":"白峰岭","f":"七言绝句","c":["仪曹苦厌为山囚，雾障烟屏看未休。","行过白峰三十里，桐庐江上重回头。"]},{"t":"兰溪县女步道中","f":"七言绝句","c":["豫樟蔽日无黄落，竹笋经霜更碧鲜。","记取江南光景异，暖烟晴日是冬天。"]},{"t":"全氏小楼与南山相对殆几案间物也暇日觞予其上索赋鄙作因口占三绝句 其一","f":"七言绝句","c":["闾阎扑地不容閒，叠起重棚翠霭间。","楼下市声喧午枕，药炉头上看青山。"]},{"t":"全氏小楼与南山相对殆几案间物也暇日觞予其上索赋鄙作因口占三绝句 其二","f":"七言绝句","c":["东篱遥见喜悠然，况在风烟咫尺间。","满劝银杯留客醉，夕阳佳处鸟飞还。"]},{"t":"予自闽中北还舟行过常秀间卧听棹歌殊有惬予心者每一句发端以声和之者三扣其辞语敷浅而鄙俚曾不若和声之欢亮也因变而作十二阕且道其传送艰苦之状亦刘连州竹枝之意云 其一","f":"七言绝句","c":["今秋湖泺两相通，差遣虽频力易攻。","度险却防连夜发，溯流还怕打头风。"]},{"t":"予自闽中北还舟行过常秀间卧听棹歌殊有惬予心者每一句发端以声和之者三扣其辞语敷浅而鄙俚曾不若和声之欢亮也因变而作十二阕且道其传送艰苦之状亦刘连州竹枝之意云 其二","f":"七言绝句","c":["两浙人稠不易安，少罹凶慊即流迁。","今年苦恼苏常地，易子营生不计钱。"]},{"t":"予自闽中北还舟行过常秀间卧听棹歌殊有惬予心者每一句发端以声和之者三扣其辞语敷浅而鄙俚曾不若和声之欢亮也因变而作十二阕且道其传送艰苦之状亦刘连州竹枝之意云 其三","f":"七言绝句","c":["朝来回棹喜空船，坐唱吴歌踏两舷。","淘米墩头风浪起，最防吹入太湖烟。"]},{"t":"予自闽中北还舟行过常秀间卧听棹歌殊有惬予心者每一句发端以声和之者三扣其辞语敷浅而鄙俚曾不若和声之欢亮也因变而作十二阕且道其传送艰苦之状亦刘连州竹枝之意云 其四","f":"七言绝句","c":["岊江滩石苦经过，音节听来燥未和。","不似吴侬音韵美，遗声全是竹枝歌。"]},{"t":"予自闽中北还舟行过常秀间卧听棹歌殊有惬予心者每一句发端以声和之者三扣其辞语敷浅而鄙俚曾不若和声之欢亮也因变而作十二阕且道其传送艰苦之状亦刘连州竹枝之意云 其五","f":"七言绝句","c":["干当江南有许多，往还冠盖似撺梭。","因兹力役无朝暮，欸乃翻成懊恼歌。"]},{"t":"题刘总管宅御爱峰","f":"七言绝句","c":["太湖清润岱宗雄，金字宣和第一峰。","绝似水晶宫里看，一堆寒碧玉玲珑。"]},{"t":"龙虎台二首 其一","f":"七言绝句","c":["翠华行殿拂明开，北狩南巡此往回。","长忆先皇重词翰，玉堂今岁几人来。"]},{"t":"龙虎台二首 其二","f":"七言绝句","c":["山灵拱护走风雷，万马云屯驻汉台。","今日鼎成弓剑在，西风吹泪不胜哀。"]},{"t":"甘不剌川在上都西北七百里外董侯承旨扈从北回遇于榆林酒间因及今秋大狝之盛书六绝以纪其事 其一","f":"七言绝句","c":["千里阴山骑四周，休誇西伯渭滨游。","今年较猎饶常岁，一色天狼四十头。"]},{"t":"甘不剌川在上都西北七百里外董侯承旨扈从北回遇于榆林酒间因及今秋大狝之盛书六绝以纪其事 其二","f":"七言绝句","c":["今年大狝蹛林秋，青兕黄羊以万筹。","摇吻戍儿欣有语，好云从此到南楼。"]},{"t":"甘不剌川在上都西北七百里外董侯承旨扈从北回遇于榆林酒间因及今秋大狝之盛书六绝以纪其事 其三","f":"七言绝句","c":["今秋天饷住冬粮，万穴空来杀气苍。","渴饮马酮饥食肉，西风低草看牛羊。"]},{"t":"题钱舜举画梨花","f":"七言绝句","c":["掖西千树闹春华，莫把芳容带雨誇。","看取一枝横绝处，洗妆还是汉宫娃。"]},{"t":"疏梅寒雀图","f":"七言绝句","c":["长记扁舟过武夷，仙家梅竹满清溪。","山禽尽日怜幽致，争拣寒枝趁晚栖。"]},{"t":"枯木寒鸦","f":"七言绝句","c":["枯树寒梢冻欲冰，野鸦翻影若为情。","锦鸠呼雨烟林外，红杏香中过一生。"]},{"t":"农里叹 其一","f":"七言绝句","c":["今岁冯夷势蹇骄，漫流西岸不知遥。","枯槎聚沫犹然在，时见田间拥树腰。"]},{"t":"农里叹 其二","f":"七言绝句","c":["洨水南来接北滹，两河会合泛田庐。","官来检验承尊重，所望申圆得早除。"]},{"t":"农里叹 其三","f":"七言绝句","c":["每年秋涨赖横堤，水纵漫堤害尚微。","近为鹿城偷堰破，放交流潦到柴扉。"]},{"t":"农里叹 其四","f":"七言绝句","c":["谷穗虚穰草色熏，满前堆积漫如囷。","一餐到口还无济，辛苦田间力稼人。"]},{"t":"玉堂即事二首 其一","f":"七言绝句","c":["阴阴槐幄幕閒庭，静似蓝田县事厅。","细草近缘春雨过，映阶侵户一时青。"]},{"t":"玉堂即事二首 其二","f":"七言绝句","c":["日长上直玉堂庐，思入閒云待卷舒。","重为明时难再遇，等闲羞老蠹鱼书。"]},{"t":"口号","f":"七言绝句","c":["隔夜端门分板位，平明簪笏列鸳行。","紫云低覆千官入，润作金炉百和香。"]},{"t":"诗寄刘清卿都事","f":"七言律诗","c":["朋簪才盍脱荷囊，兰到升庭见独芳。","毳幕夜书称快梦，冰壶孤抱映秋霜。","十年紫禁烟花近，四海金华姓字香。","南北相望固迢递，久要情在恐难忘。"]},{"t":"纪梦","f":"曲","c":["刘使君，跨苍驎，翩然而来空际云。","腰间宝玦佩两剑，青蛇跃出光粼粼。","谁谓昧平昔，款语情何亲。","复为袖出先书一卷，纸色黯惨皆奇文。","大如离堆几百字，钩络朱墨殆似髹漆新。","残梦忽随风雨断，破泉惊听怒涛奔。"]},{"t":"正宫・黑漆弩游金山寺并序","f":"曲","c":["邻曲子严伯昌尝以《黑漆弩》侑酒。","省郎仲先谓余曰：“词虽佳，曲名似未雅。","若就以‘江南烟雨’目之，何如？”予曰：“昔东坡作《念奴曲》，后人爱之，易其名曰《酹江月》，其谁曰不然？”仲先因请余效颦，遂追赋《游金山寺》一阕，倚其声而歌之。","昔汉儒家畜声妓，唐人例有音学。","而今之乐府，用力多而难为工。","纵使有成，未免笔墨劝淫为侠耳。","渠辈年少气锐，渊源正学，不致费日力于此也。","其词曰：苍波万顷孤岑矗，是一片水面上天竺。","金鳌头满咽三杯，吸尽江山浓绿。","蛟龙虚恐下燃犀，风起浪翻如屋。","任夕阳归棹纵横，待偿我平生不足。","曲山亦作《言怀》一词，遂继韵戏赠休官彭泽居闲久，纵清苦爱吾子能守。","幸年来所事消磨，只有苦吟甘酒。","平生学道在初心，富贵浮云何有？恐此身未许投闲，又待看凤麟飞走。"]},{"t":"仙吕・后庭花晚眺临武堂","f":"曲","c":["绿树连远洲，青山压树头。","落日高城望，烟霏翠满楼。","木兰舟，彼汾一曲，春风佳可游。"]}]};